    ["01-9"] = {tips={{k="交通", text="À Hurlevent, prenez le tram des profondeurs pour Forgefer. Si vous avez quitté Teldrassil tôt, embarquez d'abord à Auberdine pour Hurlevent, puis prenez le tram."}}, steps={[1]={npc="Rudra Amberstill", tgt="Rudra Amberstill", tag="Facultatif, Groupe recommandé"}, [2]={hint="Sur demande de Rudra Amberstill, tuer Vagash et rapporter un de ses crocs à la ferme des Amberstill.", tag="Facultatif, Groupe recommandé"}, [3]={npc="Rudra Amberstill", tgt="Rudra Amberstill", tag="Facultatif, Groupe recommandé"}, [4]={npc="Terre-voyant Farsen", tgt="Terre-voyant Farsen"}, [5]={npc="Terre-voyant Farsen", tgt="Terre-voyant Farsen"}, [6]={npc="Terre-voyant Farsen", tgt="Terre-voyant Farsen"}, [7]={npc="Sénateur Mehr Stonehallow", tgt="Sénateur Mehr Stonehallow"}, [8]={npc="Contremaître Stonebrow", tgt="Contremaître Stonebrow"}, [9]={hint="Tuez 10 espions sombrefer à Dun Morogh."}, [10]={npc="Carte sombrefer", npcObj=true, desc="Fais un clic droit sur Carte sombrefer dans ton sac pour lancer la quête."}, [11]={hint="Tuer 6 Brise-crânes Mâcheroc pour le contremaître Stonebrow à la carrière de Gol'Bolar."}, [12]={hint="Tuer 10 Briseurs d'os Mâcheroc pour le sénateur Mehr Stonehallow à la carrière de Gol'Bolar."}, [13]={npc="Contremaître Stonebrow", tgt="Contremaître Stonebrow"}, [14]={npc="Sénateur Mehr Stonehallow", tgt="Sénateur Mehr Stonehallow"}, [15]={npc="Terre-voyant Farsen", tgt="Terre-voyant Farsen"}, [16]={npc="Terre-voyant Farsen", tgt="Terre-voyant Farsen"}, [17]={npc="Pilote Hammerfoot", tgt="Pilote Hammerfoot"}, [18]={npc="Un cadavre de nain", npcObj=true}, [19]={npc="Un cadavre de nain", npcObj=true}, [20]={hint="Tuer Griffe galeuse."}, [21]={npc="Pilote Hammerfoot", tgt="Pilote Hammerfoot"}, [22]={text="Suis la route jusqu'à ce point."}, [23]={text="Suis la route jusqu'à ce point."}, [24]={text="Suis la route jusqu'à ce point."}, [25]={text="Suis la route jusqu'à ce point."}, [26]={npc="Montagnard Cobbleflint", tgt="Montagnard Cobb