y", tgt="Gilbert Gray"}, [124]={npc="Gilbert Gray", tgt="Gilbert Gray"}, [125]={to="Auberdine", from="Stormwind"}}},
    ["02-10"] = {steps={[1]={npc="Wizbang Cranktoggle", tgt="Wizbang Cranktoggle"}, [2]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [3]={node="Auberdine"}, [4]={hint="Réunir 6 Pattes de clampants et les mettre dans la bigobox 827.", desc="Ramassez les pattes des crabes de niveau 9-10 sur le rivage au sud d'Auberdine. Si vous n'avez pas encore la quête de la créature échouée, prenez-la à votre prochain passage sur les quais à partir du niveau 11."}, [5]={hint="Récupérer des Os de créature marine sur la créature échouée, au sud d'Auberdine, puis les apporter à Gwennyth Bly'Leggonde, à Auberdine."}, [6]={npc="Bigobox 827", npcObj=true}, [7]={npc="Bigobox 827", npcObj=true}, [8]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [9]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [10]={hint="Apporter 8 Caisses de Minerai d'Elunite et le Médaillon d'Elura à Elanaria à Darnassus."}, [11]={npc="Cerellean Whiteclaw", tgt="Cerellean Whiteclaw"}, [12]={hint="Récupérer les Restes de tortue de mer sur le Squelette de la tortue de mer, dans les eaux à l'ouest d'Auberdine, puis parler à Gwennyth Bly'Leggonde, à Auberdine."}, [13]={hint="Rassembler 3 Yeux de batteur de Sombrivage au fond de la mer, près de la bigobox 411."}, [14]={text="Suis la route jusqu'à ce point."}, [15]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [16]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [17]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [18]={npc="Terenthis", tgt="Terenthis"}, [19]={text="Suis la route jusqu'à ce point."}, [20]={hint="Capturer vivant un Ours des chardons enragé, puis le ramener à Tharnariun."}, [21]={hint="Utiliser la Poussière de lune cénarienne sur la Pierre des séléniens d'Auberdine pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu'il possède."}, [22]={npc="Asterion", tgt="Asterion"}, [23]={npc="Asterion", tgt="Asterion"}, [24]={hint="Acquérir 8 Boucles d'oreilles