    ["02-11"] = {steps={[1]={node="Stormwind"}, [2]={npc="Ilsa Corbin", tgt="Ilsa Corbin", tag="Facultatif", desc="La quête d'introduction est facultative : va directement voir Harry Burlguard à Hurlevent et accepte Bartleby le poivrot."}, [3]={npc="Harry Burlguard", tgt="Harry Burlguard", tag="Facultatif", desc="La quête d'introduction est facultative : va directement voir Harry Burlguard à Hurlevent et accepte Bartleby le poivrot."}, [4]={npc="Harry Burlguard", tgt="Harry Burlguard"}, [5]={npc="Bartleby", tgt="Bartleby"}, [6]={npc="Bartleby", tgt="Bartleby", desc="Parle à Bartleby et il t'attaque. Combats-le jusqu'à ce qu'il se rende."}, [7]={hint="Battre Bartleby, puis lui parler.", desc="Parle à Bartleby et il t'attaque. Combats-le jusqu'à ce qu'il se rende."}, [8]={npc="Bartleby", tgt="Bartleby", desc="Parle à Bartleby et il t'attaque. Combats-le jusqu'à ce qu'il se rende."}, [9]={npc="Bartleby", tgt="Bartleby"}, [10]={npc="Harry Burlguard", tgt="Harry Burlguard"}, [11]={npc="Harry Burlguard", tgt="Harry Burlguard"}, [12]={npc="Maréchal Haggard", tgt="Maréchal Haggard"}, [13]={npc="Maréchal Haggard", tgt="Maréchal Haggard", desc="Jack Dent-Morte se trouve au camp au nord du Camp de bûcherons du Val d'est, dans la forêt d'Elwynn."}, [14]={hint="Retrouver la Plaque du maréchal Haggard au Camp de Jack Dent-Morte, et la rapporter au maréchal Haggard.", desc="Jack Dent-Morte se trouve au camp au nord du Camp de bûcherons du Val d'est, dans la forêt d'Elwynn."}, [15]={npc="Maréchal Haggard", tgt="Maréchal Haggard", desc="Jack Dent-Morte se trouve au camp au nord du Camp de bûcherons du Val d'est, dans la forêt d'Elwynn."}, [16]={text="Depuis le Camp de bûcherons du Val d'est, suis la route de la Forêt d'Elwynn vers l'ouest, passe par Comté-de-l'Or et traverse le pont pour entrer dans la Marche de l'Ouest."}, [17]={npc="Gakin le Tisse-noir", tgt="Gakin le Tisse-noir"}, [18]={npc="Remen Marcot", tgt="Remen Marcot", tag="Facultatif", desc="Quête d'introduction des humai