    ["05-d1"] = {name="La salle des Thanes", entrance="Forgefer 27.63, 47.83", pickup="En passant par Dun Morogh et Loch Modan, prends d'abord les quêtes d'avant-donjon; inutile de revenir en arrière juste avant d'entrer. Les Skyborne passent {s:01-9} : lors de ta première visite à Forgefer, va vers l'est à Dun Morogh voir Terre-voyant Farsen, termine Le guet de Farsen, Étouffer le mal dans l'œuf et La carte souterraine, puis reviens à Forgefer. Si tu ne veux pas faire le détour, passe Incursion dans le Vieux Forgefer.", pickupS={{"En passant par Dun Morogh et Loch Modan, prends d'abord les quêtes d'avant-donjon; inutile de revenir en arrière juste avant d'entrer"}, {"Les Skyborne passent {s:01-9} : lors de ta première visite à Forgefer, va vers l'est à Dun Morogh voir Terre-voyant Farsen, termine Le guet de Farsen, Étouffer le mal dans l'œuf et La carte souterraine, puis reviens à Forgefer", {race={"Skyborne"}}}, {"Si tu ne veux pas faire le détour, passe Incursion dans le Vieux Forgefer"}}, steps={[1]={npc="Carte sombrefer", npcObj=true, tag="Prérequis de donjon"}, [2]={npc="Terre-voyant Farsen", tgt="Terre-voyant Farsen", tag="Prérequis de donjon"}, [3]={npc="Terre-voyant Farsen", tgt="Terre-voyant Farsen"}, [4]={npc="Afadra Mur-de-Dun", tgt="Afadra Mur-de-Dun"}, [5]={npc="Thom Filch", tgt="Thom Filch"}, [6]={text="Entrée : La salle des Thanes"}, [7]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [8]={hint="Apaisez l'esprit de Faldrim Courbenclume, puis retournez voir la domestique fantomatique dans la salle des Thanes."}, [9]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [10]={hint="Tuez 15 apparitions enragées et 10 âmes tourmentées, puis accordez le repos à l'esprit de Courbenclume."}, [11]={hint="Récupérez 8 héritages nains dans la salle des Thanes."}, [12]={hint="Pénétrez dans la salle des Thanes, sous le Vieux Forgefer, et emparez-vous de la tête de Durgen Mornemartel."}, [13]={npc="Treaty of Understanding", npcObj=true, desc="Fais un clic droit sur Traité d'entente dans ton sac pour lancer la quête. Le dernier boss lance Peur vers 35 % de vie. Nettoie d'abord les adds, puis attire le boss dans la salle précédente. Un levier se trouve à côté du donneur de quête. Actionne-le pour ouvrir la porte et sortir en ligne droite."}, [14]={npc="Thom Filch", tgt="Thom Filch"}, [15]={npc="Afadra Mur-de-Dun", tgt="Afadra Mur-de-Dun"}, [16]={npc="Roi Magni Bronzebeard", tgt="Roi Magni Bronzebeard"}, [17]={npc="Roi Magni Bronzebeard", tgt="Roi Magni Bronzebeard"}}},
    ["02-12"] = {steps={[1]={npc="Gryth Thurden", tgt="Gryth Thurden"}, [2]={node="Ironforge"}, [3]={to="Thelsamar", toA="{a:144}"}, [4]={text="Quitte Forgefer et suis la route vers l'est, traverse le tunnel du col oriental pour entrer à Loch Modan, puis suis le chemin vers le nord-est jusqu'à Thelsamar.", tag="Point de vol pas encore débloqué : la première fois, va-y à pied."}, [5]={nodeA="{a:144}", node="Thelsamar"}, [6]={npc="Montagnard Kadrell", tgt="Montagnard Kadrell"}, [7]={npc="Montagnarde Ylva", tgt="Montagnarde Ylva"}, [8]={hint="Le Montagnard Gravelgaw de la Tour de garde méridionale veut que vous tuiez 10 Brise-crâne et 10 Prophètes Brisepierre, puis que vous retourniez le voir."}, [9]={hint="Plantez l'étendard de Forgefer afin d'attirer le casse-tête trogg, tuez-le, puis faites votre rapport au capitaine Rudagite."}, [10]={npc="Montagnard Gravelgaw", tgt="Montagnard Gravelgaw"}, [11]={npc="Montagnard Wallbang", tgt="Montagnard Wallbang"}, [12]={hint="Le Montagnard Wallbang de la Tour de garde méridionale veut que vous tuiez 10 Chamans et 10 Briseurs d'Os Brisepierre."}, [13]={npc="Montagnard Wallbang", tgt="Montagnard Wallbang"}, [14]={npc="Capitaine Rugelfuss", tgt="Capitaine Rugelfuss"}, [15]={hint="Prendre le Symbole de vie et ressusciter Narm Faulk dans Dun Morogh."}, [16]={npc="Narm Faulk", tgt="Narm Faulk"}, [17]={npc="Narm Faulk", tgt="Narm Faulk"}, [18]={hint="Récupérer un Script des nains Sombrefer près du lac du Lit d'Helm et le rapporter à Muiredon Battleforge à Forgefer."}, [19]={npc="Muiredon Battleforge", tgt="Muiredon Battleforge"}, [20]={npc="Muiredon Battleforge", tgt="Muiredon Battleforge", desc="Rends la quête pour apprendre Rédemption."}, [21]={npc="Tiza Battleforge", tgt="Tiza Battleforge", desc="Rends la quête pour apprendre Rédemption."}, [22]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [23]={npc="Brock Stoneseeker", tgt="Brock Stoneseeker"}, [24]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [25]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [26]={npc="Prospecteur Ironband", tgt="Prospecteur Ironband"}, [27]={npc="Daryl le Jeune", tgt="Daryl le Jeune"}, [28]={hint="Tuer 6 Busards des montagnes et retourner auprès de Daryl le Jeune au pavillon des pérégrins en moins de 15 minutes."}, [29]={npc="Daryl le Jeune", tgt="Daryl le Jeune"}, [30]={npc="Daryl le Jeune", tgt="Daryl le Jeune"}, [31]={hint="Tuer 5 Anciens sangliers des montagnes et retourner auprès de Daryl le Jeune au pavillon des pérégrins en 12 minutes."}, [32]={npc="Daryl le Jeune", tgt="Daryl le Jeune"}, [33]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [34]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [35]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [36]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [37]={hint="Terrassez le crocilisque Daguecroc et rapportez le couteau de Marek."}, [38]={hint="Trouver 5 morceaux de Viande de cocilisque et 6 Peaux de crocilisque pour Marek Ironheart au pavillon des pérégrins."}, [39]={hint="Trouver et rapporter à Bingles son matériel :"}, [40]={npc="Ingénieur en chef Hinderweir VII", tgt="Ingénieur en chef Hinderweir VII"}, [41]={npc="Tonneau suspect", npcObj=true}, [42]={npc="Tonneau suspect", npcObj=true}, [43]={npc="Ingénieur en chef Hinderweir VII", tgt="Ingénieur en chef Hinderweir VII"}, [44]={npc="Montagnard Foudrepique", tgt="Montagnard Foudrepique", desc="Depuis le barrage, suis la route du nord vers l'ouest jusqu'à l'avant-poste du col."}, [45]={npc="Bingles Blastenheimer", tgt="Bingles Blastenheimer"}, [46]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [47]={npc="Marek Ironheart", tgt="Marek Ironheart"}, [48]={hint="Apporter 8 Idoles de pierre sculptée à Magmar Fellhew."}, [49]={npc="Magmar Fellhew", tgt="Magmar Fellhew"}, [50]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [51]={npc="Jern Hornhelm", tgt="Jern Hornhelm"}, [52]={}, [53]={npc="Argos Nightwhisper", tgt="Argos Nightwhisper"}, [54]={to="Auberdine", from="Stormwind"}}},
    ["02-13"] = {steps={[1]={npc="Gubber Blump", tgt="Gubber Blump"}, [2]={npc="On recherche : Fondeboue !", npcObj=true}, [3]={npc="Archéologue Hollee", tgt="Archéologue Hollee"}, [4]={npc="Archéologue Hollee", tgt="Archéologue Hollee"}, [5]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [6]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [7]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [8]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [9]={npc="Terenthis", tgt="Terenthis"}, [10]={npc="Terenthis", tgt="Terenthis"}, [11]={npc="Mystérieux Cristal rouge", npcObj=true}, [12]={npc="Mystérieux Cristal rouge", npcObj=true}, [13]={npc="Asterion", tgt="Asterion"}, [14]={npc="Créature marine échouée", npcObj=true}, [15]={hint="Récupérez le coffret de l'Aube argentée et le coffret du Voile de brume pour Gorbold Main-d'acier, à Auberdine. Ces deux objets se trouvent à bord des épaves des navires respectifs, au nord du village."}, [16]={npc="Bigobox 411", npcObj=true}, [17]={npc="Bigobox 411", npcObj=true}, [18]={npc="Tortue de mer échouée", npcObj=true}, [19]={text="Suis la route jusqu'à ce point.", desc="Désormais, tue les Traquelunes chétifs et les Ours des chardons enragés que tu croises."}, [20]={text="Suis la route jusqu'à ce point."}, [21]={hint="Aller au nord d'Auberdine, à la première chute d'eau, le long de la Bondissante et prélever un échantillon de l'eau de l'étang."}, [22]={hint="Collecter 6 morceaux de Belle chair de crabe pour Gubber Blump, à Auberdine."}, [23]={npc="Tortue de mer échouée", npcObj=true}, [24]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [25]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [26]={hint="Collecter 4 Parchemins passés pour Balthule Shadowstrike près de la Tour d'Althalaxx."}, [27]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [28]={npc="Balthule Shadowstrike", tgt="Balthule Shadowstrike"}, [29]={hint="Débarrasser la forêt de 20 Ours des chardons enragés et retourner voir Tharnariun Treetender, à Sombrivage."}, [30]={hint="Trouver 6 Crocs de traquelune et les mettre dans la bigobox 323."}, [31]={hint="Apporter 5 Pédoncules d'Amanite et 1 Amanite phalloïde à Barithras Moonshade à Auberdine."}, [32]={npc="Bigobox 323", npcObj=true}, [33]={npc="Bigobox 323", npcObj=true}, [34]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [35]={npc="Tharnariun Treetender", tgt="Tharnariun Treetender"}, [36]={npc="Gorbold Steelhand", tgt="Gorbold Steelhand"}, [37]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [38]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [39]={npc="Sentinelle Glynda Nal'Shea", tgt="Sentinelle Glynda Nal'Shea"}, [40]={npc="Barithras Moonshade", tgt="Barithras Moonshade", desc="Remplis le Bol de purification vide au puits de lune."}, [41]={npc="Barithras Moonshade", tgt="Barithras Moonshade"}, [42]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [43]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [44]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [45]={npc="Gubber Blump", tgt="Gubber Blump"}, [46]={npc="Créature marine échouée", npcObj=true}, [47]={npc="Créature marine échouée", npcObj=true, desc="L'événement ne se déclenche qu'à proximité du feu de camp. Fais-le maintenant ou quand l'itinéraire repassera par ici."}, [48]={npc="Tortue de mer échouée", npcObj=true}, [49]={npc="Tortue de mer échouée", npcObj=true}, [50]={npc="Créature marine échouée", npcObj=true}, [51]={text="Suis la route jusqu'à ce point."}, [52]={npc="Sentinelle Aynasha", tgt="Sentinelle Aynasha", desc="En allant à la quête suivante, tue chaque Géniteur traquelune croisé (les petits et la matriarche viendront avec)."}, [53]={hint="Protéger la Sentinelle Aynasha, puis parler à Onaeya au poste de Maestra, en Ashenvale."}, [54]={npc="Onu", tgt="Onu"}, [55]={npc="Onu", tgt="Onu"}, [56]={npc="Coupe de divination", npcObj=true, desc="Va en 39.2, 86.9 et utilise la fiole donnée par Onu pour la poser au sol."}, [57]={npc="Coupe de divination", npcObj=true}, [58]={npc="Tome du crépuscule", npcObj=true}, [59]={npc="Tome du crépuscule", npcObj=true}, [60]={npc="Tome du crépuscule", npcObj=true}, [61]={hint="Obtenez un œil sans pareil auprès d'un disciple ou d'un nervi du Crépuscule, au Glaive du Maître à Sombrivage, puis trouvez quelqu'un à Auberdine qui accepte de le prendre."}, [62]={npc="Therylune", tgt="Therylune", desc="Quête d'escorte : en groupe, attends que tout le monde en soit au même point avant de l'accepter, et désactive l'acceptation automatique."}, [63]={hint="Aider Therylune à s'échapper, puis dire à Therysil au Sanctuaire d'Aessina que sa sœur est saine et sauve."}, [64]={npc="Livre : Les puissances d'en-bas", npcObj=true, tag="Facultatif", desc="Fais un clic droit sur Livre : Les puissances d'en-bas dans ton sac pour lancer la quête. Les monstres de la fosse ont une faible chance de laisser tomber « Livre : Les puissances d'en-bas ». Accepte la quête seulement s'il tombe."}, [65]={npc="Prospecteur Remtravel", tgt="Prospecteur Remtravel", desc="Quête d'escorte : en groupe, attends que tout le monde en soit au même point avant de l'accepter, et désactive l'acceptation automatique. Laisse le prospecteur Remtravel passer devant et n'attaque que les monstres qui l'agressent en premier."}, [66]={npc="Prospecteur Remtravel", tgt="Prospecteur Remtravel"}, [67]={hint="Protéger le Prospecteur Remtravel pendant qu'il recherche le mystérieux fossile, puis revenir voir l'Archéologue Hollee à Auberdine."}, [68]={hint="Se procurer 4 Scalps vieillis sur de Vieux ours des chardons au sud d'Auberdine et les placer dans la Bigobox 525."}, [69]={npc="Bigobox 525", npcObj=true}, [70]={hint="Trouver 5 Belles peaux de traquelune et les apporter à Terenthis, à Auberdine."}, [71]={npc="Onu", tgt="Onu"}, [72]={npc="Onu", tgt="Onu"}, [73]={npc="Arbal", tgt="Arbal"}, [74]={hint="Trouver et tuer le murloc connu sous le nom de Fondeboue. On pense que la créature défend les huttes des murlocs au sud d'Auberdine près de l'eau.", desc="Plusieurs vagues de murlocs arrivent, 2-3 par vague. Éloigne le dernier murloc de chaque vague du feu de camp avant de le tuer, mange et bois, puis attire la vague suivante. Ou trouve un groupe."}, [75]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [76]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [77]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [78]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [79]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [80]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [81]={npc="Sentinelle Glynda Nal'Shea", tgt="Sentinelle Glynda Nal'Shea"}, [82]={npc="Archéologue Hollee", tgt="Archéologue Hollee"}, [83]={npc="Archéologue Hollee", tgt="Archéologue Hollee"}, [84]={npc="Thundris Windweaver", tgt="Thundris Windweaver"}, [85]={npc="Terenthis", tgt="Terenthis"}, [86]={npc="Terenthis", tgt="Terenthis"}, [87]={to="Rut'theran Village", toA="{a:702}", from="Auberdine"}, [88]={to="Rut'theran Village", toA="{a:702}"}, [89]={npc="Nessa Shadowsong", tgt="Nessa Shadowsong"}, [90]={text="Prends le portail de Rut'theran pour Darnassus."}, [91]={npc="Chef archéologue Greywhisker", tgt="Chef archéologue Greywhisker"}, [92]={npc="Chef archéologue Greywhisker", tgt="Chef archéologue Greywhisker"}, [93]={npc="Elanaria", tgt="Elanaria"}, [94]={npc="Elanaria", tgt="Elanaria"}, [95]={npc="Mathiel", tgt="Mathiel"}, [96]={npc="Mathiel", tgt="Mathiel", desc="Récompense : une arme en Elunite."}, [97]={npc="Mathiel", tgt="Mathiel", desc="Récompense : une arme en Elunite."}, [98]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Après avoir terminé « Corps et cœur » à la Pierre des séléniens d'Auberdine, retourne à Darnassus pour rendre la quête et apprendre Forme d'ours."}, [99]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", tag="Tu peux déjà acheter à l'hôtel des ventes (ou te faire envoyer par un reroll) 5 × Terrestrine (pour Rassembler les ingrédients du remède, plus tard)."}, [100]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [101]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [102]={hint="Utiliser une Fiole d'échantillon des Chutes de la Bondissante vide pour collecter un échantillon d'eau, à l'entrée de la grotte, à proximité des Chutes.", desc="Prends le vol réservé aux druides de Havrenuit à Rut'theran, puis vole vers Auberdine."}, [103]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong"}, [104]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Récolte de la Terrestrine et des Champignons lunaires à Sombrivage, puis rends-les à Auberdine. Terrestrine ×5 s'achète à l'hôtel des ventes."}, [105]={hint="Apporter 5 Terrestrines et 12 Champignons lunaires à Alanndarian Nightsong, à Auberdine ; elle pourra ainsi commencer à préparer son remède.", desc="Récolte de la Terrestrine et des Champignons lunaires à Sombrivage, puis rends-les à Auberdine."}, [106]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Récolte de la Terrestrine et des Champignons lunaires à Sombrivage, puis rends-les à Auberdine."}, [107]={npc="Alanndarian Nightsong", tgt="Alanndarian Nightsong", desc="Utilise le remède sur les cerfs malades de Sombrivage."}, [108]={hint="Utiliser le Remède pour animaux sur 10 Daims malades qui se trouvent dans Sombrivage ; ceci les soignera. Les Daims malades ont été aperçus d'abord entre le sud de la rivière Bondissante et le nord d'Auberdine ; on en trouve également tout au sud de Sombrivage, à la frontière d'Ashenvale.", desc="Utilise le remède sur les cerfs malades de Sombrivage."}, [109]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Après avoir soigné 10 cerfs, utilise Téléportation : Reflet-de-Lune pour revenir rendre la quête."}, [110]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Rends la quête pour apprendre Guérison du poison."}, [111]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Rends la quête pour apprendre Guérison du poison. Prends le vol réservé aux druides de Havrenuit à Rut'theran, puis passe par le portail du village pour entrer à Darnassus."}, [112]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker"}, [113]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [114]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Trouve le Colifichet du sanctuaire au fond du lac Elune'ara."}, [115]={hint="Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l'apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.", desc="Trouve le Colifichet du sanctuaire au fond du lac Elune'ara."}, [116]={npc="Tajarri", tgt="Tajarri", desc="Trouve le Colifichet du sanctuaire au fond du lac Elune'ara."}, [117]={npc="Tajarri", tgt="Tajarri", desc="Les deux coffres verrouillés étranges contiennent chacun la moitié d'un pendentif : l'un est au fond de la mer au nord d'Auberdine, à Sombrivage, l'autre au fond de la mer au large de la côte nord-ouest de la Marche de l'Ouest."}, [118]={hint="Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l'endroit où ces objets se trouvent.", desc="Prends le vol réservé aux druides de Havrenuit à Rut'theran, vole vers Auberdine et nage vers le nord jusqu'au coffre verrouillé au fond de la mer. Prends ensuite le bateau d'Auberdine à Hurlevent, vole vers la Colline des Sentinelles et va au nord-ouest jusqu'à la côte pour plonger et ouvrir l'autre coffre verrouillé."}, [119]={text="Une fois les deux moitiés réunies, utilise Téléportation : Reflet-de-Lune pour revenir et assembler les moitiés du pendentif près du Sanctuaire de Remulos."}, [120]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze"}, [121]={npc="Dendrite Starblaze", tgt="Dendrite Starblaze", desc="Rends la quête pour apprendre Forme aquatique."}, [122]={npc="Mathrengyl Bearwalker", tgt="Mathrengyl Bearwalker", desc="Rends la quête pour apprendre Forme aquatique. Prends le vol réservé aux druides de Havrenuit à Rut'theran, puis passe par le portail du village pour entrer à Darnassus."}, [123]={text="Prends le portail de Darnassus pour retourner à Rut'theran."}, [124]={nodeA="{a:702}", node="Rut'theran Village"}, [125]={to="Auberdine"}, [126]={hint="Trouver et tuer la Mère de la tanière."}, [127]={hint="Remplir le Bol de purification vide au Puits de lune d'Auberdine."}, [128]={hint="Apporter 6 Reliques de Mathystra à Onu, au Bosquet des Anciens."}, [129]={hint="Éliminez 12 myrmidons tempécailles, 8 ensorceleuses tempécailles et 6 guerriers tempécailles pour Arbal, au bosquet des Anciens."}, [130]={hint="Trouvez une maîtresse des bêtes tempécaille, terrassez-la et rapportez son bâtonnet de domination profonde."}, [131]={}}},
    ["05-d2"] = {name="Ruines de Lordaeron", entrance="Fossoyeuse 72.41, 11.37", steps={[1]={text="Optionnelle et éloignée : l'entrée se trouve dans les Ruines de Lordaeron, au-dessus de Fossoyeuse, ce qui oblige à traverser le territoire de la Horde. Depuis Auberdine, prends le bateau jusqu'au port de Menethil, puis suis la ligne nord jusqu'à Austrivage. Descends-y et débloque son point de vol, puis va vers le nord par les Contreforts de Hautebrande et la Forêt des Pins argentés jusqu'aux Clairières de Tirisfal. Après le donjon, utilise ta pierre de foyer pour retourner à Hurlevent et reprends à {s:02-14}.", tag="Facultatif"}, [2]={text="Entrée : Ruines de Lordaeron"}, [3]={}, [4]={npc="Insigne ensanglanté", npcObj=true, desc="Fais un clic droit sur Insigne ensanglanté dans ton sac pour lancer la quête."}, [5]={hint="Récupérez 10 insignes ensanglantés et remettez-les au général Marcus Jonathan, à Hurlevent."}, [6]={npc="Écu de Lordaeron", npcObj=true, desc="Fais un clic droit sur Écu de Lordaeron dans ton sac pour lancer la quête."}, [7]={npc="Blood-Stained Parchment", npcObj=true, desc="Fais un clic droit sur Blood-Stained Parchment dans ton sac pour lancer la quête."}, [8]={}, [9]={npc="Directrice de l'orphelinat Nightingale", tgt="Directrice de l'orphelinat Nightingale"}, [10]={npc="Dame Dena Kennedy", tgt="Dame Dena Kennedy"}, [11]={npc="Général Marcus Jonathan", tgt="Général Marcus Jonathan"}}},
    ["02-14"] = {grind={[1]={mob="Cogneur des Carmines", note="Camp de gnolls au nord de Comté-du-Lac; monstres normaux, près du point de vol."}, [2]={mob="Estafette rochenoire", note="Les orcs Rochenoire de la rive nord-est du Lac placide; niveau mieux adapté, avec des grunts parmi eux : attire-les depuis l'extérieur."}}, steps={[1]={npc="Renzik The Shiv", tgt="Renzik The Shiv"}, [2]={npc="Grande prêtresse Laurena", tgt="Grande prêtresse Laurena", desc="Accepte-la à Hurlevent, rends-la à Forgefer et apprends Gardien de peur."}, [3]={npc="Grandprêtre Rohan", tgt="Grandprêtre Rohan", desc="Accepte-la à Hurlevent, rends-la à Forgefer et apprends Gardien de peur."}, [4]={text="À Forgefer, prends le tram des profondeurs pour rentrer à Hurlevent."}, [5]={npc="Grande prêtresse Laurena", tgt="Grande prêtresse Laurena", desc="Accepte-la à Hurlevent et rends-la à Dun Morogh."}, [6]={npc="Grande prêtresse Mims", tgt="Grande prêtresse Mims", desc="Accepte-la à Hurlevent et rends-la à Dun Morogh."}, [7]={text="Retourne à Forgefer et prends le tram des profondeurs jusqu'à Hurlevent."}, [8]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="La taverne du Solitaire bleu se trouve dans le quartier des mages de Hurlevent."}, [9]={componentNpc="Rejeton de la faille", hint="Au Solitaire bleu, dans le quartier des Mages de Hurlevent, utilisez la formule. Affaiblissez une créature de la faille jusqu'à l'étourdir, utilisez le coffre puis ramassez le coffret au sol. Il en faut trois.", desc="La taverne du Solitaire bleu se trouve dans le quartier des mages de Hurlevent."}, [10]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="La taverne du Solitaire bleu se trouve dans le quartier des mages de Hurlevent."}, [11]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="Il faut 10 × Etoffe de lin et 6 × Gemme chargée de la faille. Lors d'un prochain passage au Loch Modan, entrez dans la mine par le nord (vers 35.9,18.2) et ouvrez les caisses des mineurs. En attendant, poursuivez votre route. Allez voir Wynne à Hurlevent quand le journal confirme la remise."}, [12]={npc="Wynne Larson", tgt="Wynne Larson", desc="Il faut 10 × Etoffe de lin et 6 × Gemme chargée de la faille. Lors d'un prochain passage au Loch Modan, entrez dans la mine par le nord (vers 35.9,18.2) et ouvrez les caisses des mineurs. En attendant, poursuivez votre route. Allez voir Wynne à Hurlevent quand le journal confirme la remise."}, [13]={npc="Wynne Larson", tgt="Wynne Larson", desc="Récompense : robe de tisse-mana."}, [14]={npc="Wynne Larson", tgt="Wynne Larson", desc="Récompense : robe de tisse-mana."}, [15]={npc="Gakin le Tisse-noir", tgt="Gakin le Tisse-noir"}, [16]={npc="Takar le Prophète", tgt="Takar le Prophète", desc="Prends le bateau du port de Hurlevent à Auberdine, longe la côte de Sombrivage vers le sud jusqu'à Orneval, entre dans Les Tarides par l'est via le Rempart de Mor'shan et va vers le sud trouver Takar. La Croisée et le Camp Taurajo sont des bastions de la Horde; contourne-les."}, [17]={npc="Takar le Prophète", tgt="Takar le Prophète"}, [18]={npc="Takar le Prophète", tgt="Takar le Prophète"}, [19]={hint="Trouver le Cœur du bois en Ashenvale et le porter à Gakin le Tisse-noir dans le quartier des mages de Hurlevent.", desc="Élimine d'abord les monstres près de l'arbre, puis clique sur cet arbre cénarien pour obtenir du cœur du bois."}, [20]={hint="Récupérez la Figurine en bois et rapportez-la à Gakin le Tisse-noir, au Quartier des mages de Hurlevent."}, [21]={npc="Gakin le Tisse-noir", tgt="Gakin le Tisse-noir", desc="Quand Orneval est terminé, utilise ta pierre de foyer pour retourner à Hurlevent. Si ta pierre de foyer est en recharge, retourne vers le nord jusqu'à Auberdine et prends le bateau pour Hurlevent."}, [22]={npc="Gakin le Tisse-noir", tgt="Gakin le Tisse-noir"}, [23]={npc="Gakin le Tisse-noir", tgt="Gakin le Tisse-noir", desc="Utilise-le sur le cercle d'invocation près de Gakin le Tisse-noir et vaincs la succube invoquée."}, [24]={hint="Utiliser le Noyau du cœur du bois pour invoquer et soumettre une succube, puis rapporter le Noyau de cœur du bois à Gakin le Tisse-noir, à l'Agneau assassiné.", desc="Utilise-le sur le cercle d'invocation près de Gakin le Tisse-noir et vaincs la succube invoquée."}, [25]={npc="Gakin le Tisse-noir", tgt="Gakin le Tisse-noir", desc="Utilise-le sur le cercle d'invocation près de Gakin le Tisse-noir et vaincs la succube invoquée."}, [26]={npc="Gakin le Tisse-noir", tgt="Gakin le Tisse-noir"}, [27]={hint="Utilisez la Figurine en bois pour invoquer et asservir un incube, puis rapportez l'objet à Gakin le Tisse-noir à l'Agneau assassiné."}, [28]={npc="Gakin le Tisse-noir", tgt="Gakin le Tisse-noir"}, [29]={text="Depuis Hurlevent, suis la route de la Forêt d'Elwynn vers l'est; va d'abord à la Tour d'Azora prendre L'œil attentif auprès de Theocritus; continue ensuite vers l'est jusqu'à l'entrée des Carmines pour trouver le garde Parker, puis suis la route jusqu'à Comté-du-Lac.", tag="Point de vol pas encore débloqué : la première fois, va-y à pied., Avant de partir pour les Carmines, tu peux acheter à l'hôtel des ventes (ou te faire envoyer par un reroll) 8 × Aileron de murloc (pour Les braconniers murlocs)."}, [30]={npc="Theocritus", tgt="Theocritus"}, [31]={npc="Garde Parker", tgt="Garde Parker"}, [32]={to="Lakeshire", toA="{a:69}", tag="Avant de partir pour les Carmines, tu peux acheter à l'hôtel des ventes (ou te faire envoyer par un reroll) 8 × Aileron de murloc (pour Les braconniers murlocs).", desc="Si tu n'as pas encore le point de vol de Comté-du-Lac, va de Hurlevent vers l'est par la grande route de la Forêt d'Elwynn jusqu'à Comté-du-Lac."}, [33]={npc="Garde Parker", tgt="Garde Parker", desc="Garde Parker se tient au carrefour de la route principale à l'ouest de Les Carmines, qui mène à Forêt d'Elwynn."}, [34]={npc="Darcy", tgt="Darcy"}, [35]={npc="Wiley le noir", tgt="Wiley le noir"}, [36]={npc="Wiley le noir", tgt="Wiley le noir"}, [37]={npc="Chef des docks Baren", tgt="Chef des docks Baren"}, [38]={npc="Chef des docks Baren", tgt="Chef des docks Baren", desc="L'Aileron de murloc s'achète à l'hôtel des ventes. Avec 8, pas besoin de farmer."}, [39]={npc="Magistrat Solomon", tgt="Magistrat Solomon"}, [40]={npc="Verner Osgood", tgt="Verner Osgood"}, [41]={npc="Adjoint Feldon", tgt="Adjoint Feldon"}, [42]={npc="Adjoint Feldon", tgt="Adjoint Feldon"}, [43]={npc="Adjoint Feldon", tgt="Adjoint Feldon"}, [44]={npc="Lucius", tgt="Lucius"}, [45]={npc="Lucius", tgt="Lucius", desc="Utilise Crochetage sur le coffre près de la scierie d'Alther."}, [46]={hint="Ouvrir le Coffret de Lucius, récupérer le Gage de voleur et le rapporter à Lucius à Comté-du-Lac.", desc="Utilise Crochetage sur le coffre près de la scierie d'Alther."}, [47]={npc="Lucius", tgt="Lucius", desc="Utilise Crochetage sur le coffre près de la scierie d'Alther."}, [48]={npc="Arantir", tgt="Arantir", tag="Facultatif"}, [49]={hint="Rapporter les Cornes de Nez'ra à Arantir, à Comté-du-Lac.", tag="Facultatif"}, [50]={npc="Arantir", tgt="Arantir", tag="Facultatif"}, [51]={nodeA="{a:69}", node="Lakeshire"}, [52]={npc="Yorus Barleybrew", tgt="Yorus Barleybrew", desc="Les cavernes de Rethban se trouvent au nord-ouest des Carmines et sont pleines d'ogres."}, [53]={npc="Yorus Barleybrew", tgt="Yorus Barleybrew", desc="Les cavernes de Rethban se trouvent au nord-ouest des Carmines et sont pleines d'ogres."}, [54]={npc="Yorus Barleybrew", tgt="Yorus Barleybrew"}, [55]={desc="Si tu n'es pas encore niveau 21 avant de quitter les Carmines, va au camp de gnolls au nord de Comté-du-Lac et monte au niveau 21 en tuant des Cogneurs des Carmines."}, [56]={to="Sentinel Hill", toA="{a:108}"}, [57]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [58]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [59]={to="Stormwind"}, [60]={npc="Grande prêtresse Laurena", tgt="Grande prêtresse Laurena", desc="Apprends Réaction."}, [61]={npc="Grande prêtresse Laurena", tgt="Grande prêtresse Laurena", desc="Apprends Réaction."}, [63]={npc="Général Marcus Jonathan", tgt="Général Marcus Jonathan"}, [64]={npc="Furen Longbeard", tgt="Furen Longbeard"}, [65]={npc="Furen Longbeard", tgt="Furen Longbeard", tag="Si tu peux affronter des monstres de haut niveau, Groupe recommandé, Facultatif"}, [66]={hint="Réunir les matériaux dont Furen Longbeard a besoin et lui apporter à Hurlevent.", tag="Si tu peux affronter des monstres de haut niveau, Groupe recommandé, Facultatif"}, [67]={npc="Furen Longbeard", tgt="Furen Longbeard"}, [68]={npc="Furen Longbeard", tgt="Furen Longbeard"}, [69]={npc="Furen Longbeard", tgt="Furen Longbeard"}, [70]={npc="Furen Longbeard", tgt="Furen Longbeard"}, [71]={npc="Furen Longbeard", tgt="Furen Longbeard"}, [72]={npc="Furen Longbeard", tgt="Furen Longbeard"}, [74]={npc="Général Marcus Jonathan", tgt="Général Marcus Jonathan"}, [75]={npc="Argus le forgeron", tgt="Argus le forgeron"}, [76]={npc="Argus le forgeron", tgt="Argus le forgeron"}, [77]={npc="Maître Mathias Shaw", tgt="Maître Mathias Shaw"}, [78]={npc="Maître Mathias Shaw", tgt="Maître Mathias Shaw"}, [79]={npc="Maître Mathias Shaw", tgt="Maître Mathias Shaw"}, [80]={to="Sentinel Hill", toA="{a:108}"}, [81]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [82]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [83]={hint="Traquer le Messager défias dans la marche de l'Ouest et apporter les documents qu'il transporte à Stoutmantle."}, [84]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [85]={npc="Le traître défias", tgt="Le traître défias"}, [86]={hint="Escortez le Traître défias jusqu'à la cache secrète de la Confrérie défias. Lorsque vous saurez où se cachent VanCleef et ses hommes, rapportez l'information à Gryan Stoutmantle.", tag="Escorte", desc="Suis le traître défias jusqu'à Ruisselune; les monstres sur le chemin l'attaquent, aide-le. Une fois arrivé, retourne à la Colline des sentinelles."}, [87]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [88]={npc="Agent Kearnen", tgt="Agent Kearnen"}, [89]={npc="Agent Kearnen", tgt="Agent Kearnen", desc="Vole la lettre scellée dans la tour défias de la Marche de l'Ouest. Ensuite, apprends Poisons."}, [90]={hint="Voler la Clé de la Tour défias, pénétrer dans la Tour et trouver ce que contient le Coffre du bois de la Pénombre. Rapporter les informations à Mathias Shaw à Hurlevent. Lire le journal de Kearnen pour savoir ce qui se passe dans la Tour.", desc="Vole la lettre scellée dans la tour défias de la Marche de l'Ouest. Ensuite, apprends Poisons."}, [91]={npc="Une lettre qui n'a pas été envoyée.", npcObj=true, tag="Si l'objet tombe", desc="Lâché par VanCleef dans les Mortemines : clic droit dessus pour prendre la quête."}, [92]={}, [93]={npc="Maître Mathias Shaw", tgt="Maître Mathias Shaw", desc="Vole la lettre scellée dans la tour défias de la Marche de l'Ouest. Ensuite, apprends Poisons."}, [94]={npc="Maître Mathias Shaw", tgt="Maître Mathias Shaw", tag="Facultatif"}, [95]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Facultatif"}, [96]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Facultatif"}, [97]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Facultatif"}, [98]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Facultatif", desc="Fleurs sauvages simples et Fiole plombée se vendent chez les marchands. Tube en bronze s'achète à l'hôtel des ventes. Bobine de fil de soie chartreuse se ramasse dans la boutique de couture des Canaux de Hurlevent."}, [99]={hint="Apporter au docteur Mixilpixil une Brassée de Fleurs sauvages simples, une Fiole plombée, un Tube en Bronze et une Bobine de Fil de soie chartreuse. Le itis ne guérit pas tout seul.", tag="Facultatif"}, [100]={npc="Doc Mixilpixil", tgt="Doc Mixilpixil", tag="Facultatif"}, [102]={text="Tube en bronze", npc="Billibub Cogspinner", desc="Stock limité. Achète-le seulement s'il est disponible."}, [103]={npc="Baros Alexston", tgt="Baros Alexston"}, [104]={npc="Baros Alexston", tgt="Baros Alexston"}, [105]={npc="Gardien Thelwater", tgt="Gardien Thelwater"}, [106]={npc="Duthorian Rall", tgt="Duthorian Rall"}, [107]={npc="Duthorian Rall", tgt="Duthorian Rall"}, [108]={npc="Tome de valeur", npcObj=true, desc="Fais un clic droit sur Tome de la bravoure dans ton sac pour lancer la quête."}, [109]={npc="Duthorian Rall", tgt="Duthorian Rall", desc="Fais un clic droit sur Tome de la bravoure dans ton sac pour lancer la quête."}, [110]={npc="Duthorian Rall", tgt="Duthorian Rall"}, [111]={npc="Daphne Stilwell", tgt="Daphne Stilwell"}, [112]={npc="Daphne Stilwell", tgt="Daphne Stilwell", desc="Escorte Daphne Stilwell. Des Défias te tendent une embuscade en chemin."}, [113]={npc="Daphne Stilwell", tgt="Daphne Stilwell", desc="Escorte Daphne Stilwell. Des Défias te tendent une embuscade en chemin."}, [114]={npc="Daphne Stilwell", tgt="Daphne Stilwell"}, [115]={npc="Duthorian Rall", tgt="Duthorian Rall"}, [116]={npc="Duthorian Rall", tgt="Duthorian Rall"}, [117]={npc="Jordan Stilwell", tgt="Jordan Stilwell"}, [118]={npc="Jordan Stilwell", tgt="Jordan Stilwell", desc="Nécessite des matériaux comme une Gemme de Kor et la Cargaison de minerai de Bailor."}, [119]={hint="Utiliser les Notes sur les armes de Jordan, trouver du Bois de chêne de blanchepierre, la Cargaison de Minerai raffiné de Bailor, le Marteau de forge de Jordan et une Gemme de Kor, puis revenir voir Jordan Stilwell à Forgefer.", desc="Nécessite des matériaux comme une Gemme de Kor et la Cargaison de minerai de Bailor."}, [120]={npc="Jordan Stilwell", tgt="Jordan Stilwell", desc="Nécessite des matériaux comme une Gemme de Kor et la Cargaison de minerai de Bailor."}, [121]={npc="Thundris Windweaver", tgt="Thundris Windweaver", tag="Facultatif"}, [122]={hint="Apporter une Gemme de Kor à Thundris Windweaver à Sombrivage.", tag="Facultatif"}, [123]={npc="Thundris Windweaver", tgt="Thundris Windweaver", tag="Facultatif"}, [124]={npc="Bailor Stonehand", tgt="Bailor Stonehand", tag="Facultatif"}, [125]={hint="Apporter la Cargaison de minerai de Jordan à Bailor Stonehand au Loch Modan.", tag="Facultatif"}, [126]={npc="Bailor Stonehand", tgt="Bailor Stonehand", tag="Facultatif"}, [127]={npc="Jordan Stilwell", tgt="Jordan Stilwell"}, [128]={npc="Jordan Stilwell", tgt="Jordan Stilwell"}, [129]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [130]={npc="Grimand Elmore", tgt="Grimand Elmore", tag="Si tu peux affronter des monstres de haut niveau, Facultatif"}, [131]={hint="Rapporter 20 Fioles de sang ardent et 1 Roc ardent à Grimand Elmore à Hurlevent.", tag="Si tu peux affronter des monstres de haut niveau, Facultatif"}, [132]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [133]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [134]={npc="Grimand Elmore", tgt="Grimand Elmore"}}},
    ["05-d3"] = {name="Les Mortemines", entrance="Marche de l'Ouest 42.50, 71.70", pickup="Prends les quêtes du donjon dès ton passage : Marche de l'Ouest. Inutile de revenir exprès avant le donjon.", pickupS={{"Prends les quêtes du donjon dès ton passage : Marche de l'Ouest"}, {"Inutile de revenir exprès avant le donjon"}}, steps={[1]={npc="Shoni la Silencieuse", tgt="Shoni la Silencieuse"}, [2]={npc="Wilder Crispechardon", tgt="Wilder Crispechardon"}, [3]={npc="Wilder Crispechardon", tgt="Wilder Crispechardon"}, [4]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Prérequis de donjon"}, [5]={npc="Wiley le noir", tgt="Wiley le noir", tag="Prérequis de donjon"}, [6]={npc="Wiley le noir", tgt="Wiley le noir", tag="Prérequis de donjon"}, [7]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Prérequis de donjon"}, [8]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Prérequis de donjon"}, [9]={npc="Maître Mathias Shaw", tgt="Maître Mathias Shaw", tag="Prérequis de donjon"}, [10]={npc="Maître Mathias Shaw", tgt="Maître Mathias Shaw", tag="Prérequis de donjon"}, [11]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Prérequis de donjon"}, [12]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Prérequis de donjon"}, [13]={hint="Traquer le Messager défias dans la marche de l'Ouest et apporter les documents qu'il transporte à Stoutmantle.", tag="Prérequis de donjon"}, [14]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Prérequis de donjon"}, [15]={npc="Le traître défias", tgt="Le traître défias", tag="Prérequis de donjon"}, [16]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle", tag="Prérequis de donjon"}, [17]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [18]={npc="Eclaireur Riell", tgt="Eclaireur Riell"}, [19]={npc="Alba Lunepâle", tgt="Alba Lunepâle", tag="Prérequis de donjon"}, [20]={hint="Utilisez le kit d'échantillonnage d'eau de puits pour collecter des échantillons dans les puits de la ferme des Jansen et de la ferme d