npc="Manifestation d'eau mineure", tgt="Manifestation d'eau mineure", desc="Les petits esprits d'eau sont près de l'autel de l'étang, dans les Maleterres de l'ouest."}, [82]={npc="Manifestation d'eau mineure", tgt="Manifestation d'eau mineure"}, [83]={npc="Norric Lochthane", tgt="Norric Lochthane", desc="Vole de la Colline des Sentinelles à Thelsamar."}, [84]={}}},
    ["05-d6"] = {name="Excavation Site: Wetlands", nameA="{a:16732}", entrance="Les Paluns 47.79, 56.16", pickup="Prenez la quête auprès de Caitlin au port de Menethil.", pickupS={{"Prenez la quête auprès de Caitlin au port de Menethil"}}, steps={[1]={npc="Rethiel le Gouverneur vert", tgt="Rethiel le Gouverneur vert", tag="Facultatif"}, [2]={npc="Rethiel le Gouverneur vert", tgt="Rethiel le Gouverneur vert", tag="Facultatif, Groupe recommandé"}, [3]={npc="James Halloran", tgt="James Halloran", tag="Facultatif"}, [4]={npc="James Halloran", tgt="James Halloran", tag="Facultatif, Groupe recommandé"}, [5]={npc="Caitlin Grassman", tgt="Caitlin Grassman"}, [6]={npc="Caitlin Grassman", tgt="Caitlin Grassman"}, [7]={text="Prérequis : À la recherche de Lame-chantante", tag="Facultatif, Groupe recommandé"}, [8]={text="Si tu es déjà rentré à Hurlevent avec ta pierre de foyer, vole d'abord jusqu'au Port de Menethil, puis, depuis le Port de Menethil, suis la route des Paluns vers l'est jusqu'aux excavations."}, [9]={text="Entrée : Excavation Site: Wetlands"}, [10]={hint="Rapportez 4 peaux de raptor des fourrés à James Halloran, le tanneur, au port de Menethil.", tag="Facultatif, Groupe recommandé"}, [11]={hint="Tuez une horreur des hautes-terres dans les excavations et rapportez son cœur-racine à Rethiel le Gardien vert dans les Paluns.", tag="Facultatif, Groupe recommandé"}, [12]={hint="Trouver Ardin Grassman dans les excavations"}, [13]={}, [14]={}, [15]={hint="Cherchez Daewyn, le frère de Dorin Lame-chantante, dans les Excavations de Whelgar.", tag="Facultatif, Groupe recommandé"}, [16]={npc="Daewyn Songblade", tag="Facultatif, Groupe recommandé"}, [17]={npc="Daewyn Songblade", tag="Facultatif, Groupe recommandé", desc="Lors de votre prochain passage à Comté-du-Lac, dites à Dorin ce qui est arrivé à son frère."}, [18]={npc="Relique des Titans", npcObj=true, tag="Facultatif, Si l'objet tombe", desc="Si tu ramasses la relique des Titans sur le Gardien des reliques, fais un clic