    ["02-17"] = {steps={[1]={to="Lakeshire", toA="{a:69}", tag="Point de vol pas encore débloqué : la première fois, va-y à pied.", desc="Si tu as débloqué le point de vol de Sombre-comté, vole directement jusqu'à Sombre-comté. Sinon, vole jusqu'à Comté-du-Lac, suis la route vers l'ouest jusqu'au carrefour à l'ouest des Carmines, puis va vers le sud à travers le bois de la Pénombre jusqu'à Sombre-comté."}, [2]={npc="Madame Eva", tgt="Madame Eva", desc="En traversant le bois de la Pénombre, tue des araignées pour des Pattes d'araignée fondantes."}, [3]={npc="Madame Eva", tgt="Madame Eva"}, [4]={npc="Greffier Daltry", tgt="Greffier Daltry"}, [5]={npc="Greffier Daltry", tgt="Greffier Daltry"}, [6]={npc="Sirra Von'Indi", tgt="Sirra Von'Indi"}, [7]={npc="Commandant Althea Ebonlocke", tgt="Commandant Althea Ebonlocke"}, [8]={npc="Elaine Carevin", tgt="Elaine Carevin"}, [9]={npc="Elaine Carevin", tgt="Elaine Carevin"}, [10]={npc="Elaine Carevin", tgt="Elaine Carevin"}, [11]={nodeA="{a:42}", node="Darkshire"}, [12]={text="Tube en bronze", desc="Stock limité. Achète-le seulement s'il est disponible et que tu ne l'as pas encore."}, [13]={npc="Viktori Prism'Antras", tgt="Viktori Prism'Antras", desc="La chaîne d'observation des étoiles nécessite un Tube en bronze pour commencer. Si tu n'en as pas, fais d'abord le reste et achète-le plus tard à l'hôtel des ventes."}, [14]={npc="Arc de Merrick", npcObj=true, tag="Facultatif", desc="Fais un clic droit sur Arc de Merrick dans ton sac pour lancer la quête."}, [15]={npc="Bath'rah la Vigie des vents", tgt="Bath'rah la Vigie des vents", npcObj=true, tag="Facultatif", desc="Clique droit sur la Dague d'Ira dans ton sac pour prendre la quête."}, [16]={npc="Viktori Prism'Antras", tgt="Viktori Prism'Antras"}, [17]={npc="Viktori Prism'Antras", tgt="Viktori Prism'Antras"}, [18]={npc="Marie l'aveugle", tgt="Marie l'aveugle"}, [19]={npc="Marie l'aveugle", tgt="Marie l'aveugle"}, [20]={hint="Prendre le miroir de Marie l'Aveugle à la Goule folle et l'apporter à Viktori de Darkshire."}, [21]={hint="Le commandant Althea Ebonlocke de Darkshire veut que vous tuiez 8 Guerriers squelettes et 6 Mages squelettes."}, [22]={npc="Gardien Dodds", tgt="Gardien Dodds"}, [23]={hint="Fouillez la Colline-aux-Corbeaux à la recherche de tout élément intéressant, puis retournez voir Sirra Von'Indi à Sombre-Comté."}, [24]={npc="La Tremblotte", tgt="La Tremblotte"}, [25]={npc="La Tremblotte", tgt="La Tremblotte"}, [26]={npc="Sven Yorgen", tgt="Sven Yorgen"}, [27]={npc="Sven Yorgen", tgt="Sven Yorgen"}, [28]={npc="Lars", tgt="Lars"}, [29]={hint="Tuer 12 Loups redoutables affamés et 8 Loups redoutables enragés, puis retourner auprès de Lars au camp de Sven à la frontière ouest du bois de la Pénombre.", desc="Garde tes Pattes d'araignée fondantes, ne les vends pas : tu les rendras plus tard."}, [30]={hint="Tuer 15 Araignées Tisse-venin pygmées, puis rendre compte à la Sentinelle Dodds au bois de la Pénombre."}, [31]={hint="Terrassez 8 guerriers Brisepoing et 4 sous-chefs Brisepoing, puis retournez voir Sirra Von'Indi à Sombre-Comté pour en savoir plus.", tag="Facultatif", desc="Ne la fais que si tu as l'Arc de Merrick."}, [32]={hint="Terrassez 10 jeunes ravageurs noirs et 7 ravageurs noirs, puis retournez voir Sirra Von'Indi à Sombre-Comté pour de plus amples informations.", tag="Facultatif", desc="Ne la fais que si tu as la Dague d'Ira."}, [33]={npc="Abercrombie", tgt="Abercrombie"}, [34]={npc="Abercrombie", tgt="Abercrombie"}, [35]={npc="Lars", tgt="Lars"}, [36]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [37]={npc="Gryan Stoutmantle", tgt="Gryan Stoutmantle"}, [38]={npc="Vieille Cantine", npcObj=true}, [39]={npc="Vieille Cantine", npcObj=true}, [40]={to="Darkshire", toA="{a:42}"}, [41]={npc="Madame Eva", tgt="Madame Eva"}, [42]={npc="Madame Eva", tgt="Madame Eva"}, [43]={npc="Chef Grual", tgt="Chef Grual"}, [44]={npc="Chef Grual", tgt="Chef Grual"}, [45]={npc="Commandant Althea Ebonlocke", tgt="Commandant Althea Ebonlock