    ["05-d4"] = {name="La Prison", entrance="Hurlevent 52.41, 70.01", pickup="Prenez « Ce qui se passait ailleurs… » à Comté-du-Lac et « Crime et Châtiments » à Sombre-Comté. Pour « Les Emeutes de la Prison », rendez d'abord la lettre trouvée sur VanCleef. Si vous ne l'avez pas, faites les autres quêtes. Formez un groupe pour « Fureur dans les Profondeurs » après avoir terminé « La guerre contre les Sombrefer » dans les Paluns.", pickupS={{"Prenez « Ce qui se passait ailleurs… » à Comté-du-Lac et « Crime et Châtiments » à Sombre-Comté"}, {"Pour « Les Emeutes de la Prison », rendez d'abord la lettre trouvée sur VanCleef"}, {"Si vous ne l'avez pas, faites les autres quêtes"}, {"Formez un groupe pour « Fureur dans les Profondeurs » après avoir terminé « La guerre contre les Sombrefer » dans les Paluns"}}, steps={[1]={npc="Conseiller Millstipe", tgt="Conseiller Millstipe"}, [2]={text="Prérequis : Ce qui se passait ailleurs…"}, [3]={npc="Une lettre qui n'a pas été envoyée.", npcObj=true, tag="Si l'objet tombe", desc="Lâché par VanCleef dans les Mortemines : clic droit dessus pour prendre la quête."}, [4]={npc="Baros Alexston", tgt="Baros Alexston"}, [5]={npc="Baros Alexston", tgt="Baros Alexston"}, [6]={npc="Gardien Thelwater", tgt="Gardien Thelwater"}, [7]={npc="Gardien Thelwater", tgt="Gardien Thelwater"}, [8]={npc="Gardien Thelwater", tgt="Gardien Thelwater"}, [9]={npc="Nikova Raskol", tgt="Nikova Raskol"}, [10]={text="Entrée : La Prison"}, [11]={hint="Tuer 10 Prisonniers défias, 8 Détenus défias et 8 Insurgés défias dans la Prison pour le Gardien Thelwater de Hurlevent."}, [12]={hint="Tuer Bazil Thredd et ramener sa tête au Gardien Thelwater à la Prison."}, [13]={hint="Rapporter 10 foulards en laine rouge à Nikova Raskol de Hurlevent."}, [14]={hint="Le conseiller Millstipe de Darkshire désire que vous lui rameniez la main de Dextren Ward."}, [15]={hint="Ramener la tête de Targorr le Terrifiant au Garde Berton à Comté-du-Lac.", tag="Groupe recommandé, Facultatif"}, [16]={hint="Rapportez la tête de Kam Deepfury à Motley Garmason à Dun Modr.", tag="Groupe recommandé, Facultatif"}, [17]={npc="Gardien Thelwater", tgt="Gardien Thelwater"}, [18]={npc="Gardien Thelwater", tgt="Gardien Thelwater"}, [19]={npc="Nikova Raskol", tgt="Nikova Raskol"}, [20]={npc="Garde Berton", tgt="Garde Berton", tag="Groupe recommandé, Facultatif, À faire plus tard en passant", desc="Garde-la jusqu'à {s:02-19} de 02, quand tu repasseras par Comté-du-Lac, pour la rendre."}, [21]={npc="Conseiller Millstipe", tgt="Conseiller Millstipe", tag="Facultatif, Groupe recommandé, À faire plus tard en passant", desc="Garde-la jusqu'à {s:03-22} de 03, quand tu repasseras par Sombre-comté, pour la rendre."}, [22]={npc="Motley Garmason", tgt="Motley Garmason", tag="Groupe recommandé, À faire plus tard en passant"}}},
    ["02-18"] = {steps={[1]={npc="Gardien Thelwater", tgt="Gardien Thelwater", desc="Disponible seulement après avoir fait la Prison de Hurlevent (Les Emeutes de la Prison)."}, [2]={npc="Baros Alexston", tgt="Baros Alexston"}, [3]={npc="Baros Alexston", tgt="Baros Alexston"}, [4]={npc="Maître Mathias Shaw", tgt="Maître Mathias Shaw"}, [5]={npc="Maître Mathias Shaw", tgt="Maître Mathias Shaw"}, [6]={npc="Elling Trias", tgt="Elling Trias"}, [7]={npc="Elling Trias", tgt="Elling Trias"}, [8]={npc="Tyrion", tgt="Tyrion"}, [9]={npc="Tyrion", tgt="Tyrion", tag="Facultatif, Nécessite du matériel", desc="Etoffe de soie ×3 s'achète à l'hôtel des ventes."}}},
    ["02-19"] = {steps={[1]={to="Lakeshire", toA="{a:69}"}, [2]={npc="Contremaître Oslow", tgt="Contremaître Oslow"}, [3]={npc="Verner Osgood", tgt="Verner Osgood"}, [4]={npc="Dorin Songblade", tgt="Dorin Songblade", tag="Facultatif, Groupe recommandé"}, [5]={npc="Dorin Songblade", tgt="Dorin Songblade", tag="Facultatif, Groupe recommandé", desc="Si vous avez déjà terminé le site de fouilles des Paluns, acceptez cette quête à Comté-du-Lac et cherchez Daewyn lors de votre prochaine sortie en groupe."}, [6]={npc="Recherché : Gath'Ilzogg", npcObj=true, tag="Facultatif, Groupe recommandé"}, [7]={npc="Avis de recherche : incinérateur Gar'im", npcObj=true, tag="Facultatif, Groupe recommandé"}, [8]={npc="Magistrat Solomon", tgt="Magistrat Solomon"}, [9]={npc="Magistrat Solomon", tgt="Magistrat Solomon"}, [10]={npc="On recherche : lieutenant Fangore", npcObj=true}, [11]={npc="Martie Jainrose", tgt="Martie Jainrose"}, [12]={hint="Martie Jainrose de Comté-du-Lac veut que vous tuiez Fouailleventre. Ramenez-lui ses défenses comme preuve."}, [13]={npc="Maréchal Haggard", tgt="Maréchal Haggard"}, [14]={npc="Maréchal Haggard", tgt="Maréchal Haggard"}, [15]={npc="Maréchal Haggard", tgt="Maréchal Haggard", desc="Monte à l'étage et ouvre le coffre."}, [16]={npc="Maréchal Haggard", tgt="Maréchal Haggard"}, [17]={npc="Theocritus", tgt="Theocritus"}, [18]={npc="Garde Howe", tgt="Garde Howe"}, [19]={hint="Apportez le bâton brisé de l'incinérateur Gar'im au magistrat Salomon à Comté-du-Lac.", tag="Facultatif, Groupe recommandé"}, [20]={npc="Statue du vieux lion", npcObj=true, desc="Cherchez la statue de lion dehors, à l'est de la tour d'Ilgalar, et déposez-y le glyphe."}, [21]={npc="Statue du vieux lion", npcObj=true, tag="Facultatif, Groupe recommandé", desc="Si vous ne trouvez plus le glyphe fourni, vérifiez vos sacs, votre banque et votre journal de quêtes."}, [22]={hint="Depuis le lion, allez vers l'ouest jusqu'à la tour de guet intacte près du donjon de Guet-de-Pierre. Montez la rampe jusqu'au toit et cherchez la jarre vide sur les tonneaux. Attention aux gardes élites.", tag="Facultatif, Groupe recommandé"}, [23]={npc="Une jarre vide", npcObj=true, tag="Facultatif, Groupe recommandé", desc="La jarre vide est en haut de la tour de guet; la suite Morganth n'est pas dans l'itinéraire."}, [24]={hint="Tuer Gath'Ilzogg et apporter sa Tête au magistrat Solomon de Comté-du-Lac pour toucher la récompense.", tag="Facultatif, Groupe recommandé"}, [25]={hint="Rapporter la Tête de Tharil'zun au maréchal Marris, dans les Carmines.", tag="Facultatif, Groupe recommandé"}, [26]={hint="Apporter 3 Orbes de minuit au maréchal Marris à Comté-du-Lac.", tag="Facultatif, Groupe recommandé"}, [27]={hint="Apporter 10 Pendentifs sombrepoil au Bailli Conacher à l'Hôtel de ville de Comté-du-Lac.", desc="Remontez le côté est de la vallée vers le camp du nord en ramassant les pendentifs des gnolls. Des gnolls de plus bas niveau se trouvent également en bordure de la vallée."}, [28]={hint="Montez les escaliers de la tour d'Ilgalar, dans les Carmines, et prenez le livre sur l'étagère. Attention aux gardes et à l'élite. Revenez plus tard si le passage est trop dangereux.", desc="Montez les escaliers de la tour d'Ilgalar, dans les Carmines, et prenez le livre sur l'étagère. Attention aux gardes et à l'élite. Revenez plus tard si le passage est trop dangereux."}, [29]={hint="Tuer le lieutenant Fangore et rapporter sa patte au magistrat Solomon de Comté-du-Lac.", desc="Remontez le côté est de la vallée vers le nord pour trouver le lieutenant Fangore. Depuis le bord du camp, éliminez les gnolls à proximité avant de l'approcher. Ramassez en chemin les pendentifs qui vous manquent."}, [30]={hint="Éliminez 12 grandes tarentules et détruisez 6 œufs de tarentule à la scierie d'Alther, dans les Carmines, pour aider le contremaître Oslow."}, [31]={hint="Tuez 15 Champions rochenoires et le garde Howe de Comté-du-Lac vous récompensera.", desc="Suivez la route vers les Steppes ardentes jusqu'au camp sur son côté ouest. Cherchez d'abord les champions rochenoires près de l'entrée de la grotte. Entrez si le journal indique qu'il vous en manque encore."}, [32]={hint="Rapporter la patte de Couineur à Verner Osgood à Comté-du-Lac."}, [33]={npc="Martie Jainrose", tgt="Martie Jainrose"}, [34]={npc="Bailli Conacher", tgt="Bailli Conacher"}, [35]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Facultatif, Groupe recommandé"}, [36]={npc="Magistrat Solomon", tgt="Magistrat Solomon"}, [37]={npc="Magistrat Solomon", tgt="Magistrat Solomon", tag="Facultatif, Groupe recommandé"}, [38]={npc="Verner Osgood", tgt="Verner Osgood"}, [39]={npc="Contremaître Oslow", tgt="Contremaître Oslow"}, [40]={npc="Maréchal Marris", tgt="Maréchal Marris", tag="Facultatif"}, [41]={npc="Maréchal Marris", tgt="Maréchal Marris", tag="Facultatif"}, [42]={npc="Garde Howe", tgt="Garde Howe"}, [43]={to="Darkshire", toA="{a:42}"}, [44]={npc="Smitts l'aubergiste", tgt="Smitts l'aubergiste"}, [45]={npc="Smitts l'aubergiste", tgt="Smitts l'aubergiste"}, [46]={npc="Chef Grual", tgt="Chef Grual"}, [47]={npc="Chef Grual", tgt="Chef Grual"}, [48]={npc="Commandant Althea Ebonlocke", tgt="Commandant Althea Ebonlocke"}, [49]={npc="Commandant Althea Ebonlocke", tgt="Commandant Althea Ebonlocke"}, [50]={npc="Greffier Daltry", tgt="Greffier Daltry"}, [51]={npc="Greffier Daltry", tgt="Greffier Daltry"}, [52]={npc="Seigneur Ello Ebonlocke", tgt="Seigneur Ello Ebonlocke"}, [53]={npc="Commandant Althea Ebonlocke", tgt="Commandant Althea Ebonlocke"}, [54]={npc="Commandant Althea Ebonlocke", tgt="Commandant Althea Ebonlocke"}, [55]={hint="Ramassez 8 soies de quête. Au sud-est de Sombre-Comté, cherchez Jeune veuve noire. À l'ouest, près de la Colline-aux-Corbeaux, Jeune veuve noire et Solitaire putride peuvent donner la soie en surface."}, [56]={}, [57]={npc="Wynne Larson", tgt="Wynne Larson", desc="Il faut 10 × Etoffe de lin et 6 × Gemme chargée de la faille. Lors d'un prochain passage au Loch Modan, entrez dans la mine par le nord (vers 35.9,18.2) et ouvrez les caisses des mineurs. En attendant, poursuivez votre route. Allez voir Wynne à Hurlevent quand le journal confirme la remise."}, [58]={npc="Wynne Larson", tgt="Wynne Larson", desc="Récompense : robe de tisse-mana."}, [59]={npc="Wynne Larson", tgt="Wynne Larson", desc="Récompense : robe de tisse-mana."}, [60]={npc="Grand sorcier Andromath", tgt="Grand sorcier Andromath"}, [61]={npc="Grand sorcier Andromath", tgt="Grand sorcier Andromath"}, [62]={npc="Grand sorcier Andromath", tgt="Grand sorcier Andromath", desc="Une fois la quête acceptée, ramassez la soie lors de votre prochain passage au bois de la Pénombre. Le totem d'infliction vous ramène près des mêmes araignées à l'ouest."}, [63]={npc="Wynne Larson", tgt="Wynne Larson"}, [64]={npc="Wynne Larson", tgt="Wynne Larson", desc="Récompense : habit du nœud astral."}, [65]={npc="Wynne Larson", tgt="Wynne Larson", desc="Récompense : habit du nœud astral."}}},
