    ["05-d5"] = {name="Profondeurs de Brassenoire", entrance="Orneval 14.50, 14.20", pickup="En arrivant à Sombrivage (2e visite), prends d'abord Recherches sur la corruption. Les trois quêtes de Darnassus et de Forgefer demandent les niveaux 18-20; prends-les en passant quand tu as le niveau.", pickupS={{"En arrivant à Sombrivage (2e visite), prends d'abord Recherches sur la corruption"}, {"Les trois quêtes de Darnassus et de Forgefer demandent les niveaux 18-20; prends-les en passant quand tu as le niveau"}}, steps={[1]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [2]={npc="Garde d'argent Manados", tgt="Garde d'argent Manados", desc="Niveau 20 requis. Si tu n'as pas encore le niveau en entrant à Darnassus à {s:02-13}, prends-la à un prochain passage ou passe-la."}, [3]={npc="Veilleur de l'aube Shaedlass", tgt="Veilleur de l'aube Shaedlass", desc="Niveau 18 requis; prends-la au passage en entrant à Darnassus à {s:02-13}."}, [4]={npc="Gerrig Bonegrip", tgt="Gerrig Bonegrip", desc="Niveau 18 requis. Au prochain passage à Hurlevent, prends le tram des profondeurs jusqu'à Forgefer pour l'accepter, ou passe-la si tu ne veux pas t'y rendre exprès."}, [5]={text="Entrée : Profondeurs de Brassenoire"}, [6]={hint="Apporter le « Manuscrit de Lorgalis » à Gerrig Bonegrip à Forgefer."}, [7]={hint="Gershala Nightwhisper d'Auberdine veut 8 Souches de cerveau corrompu."}, [8]={npc="Garde d'argent Thaelrid", tgt="Garde d'argent Thaelrid"}, [9]={npc="Garde d'argent Thaelrid", tgt="Garde d'argent Thaelrid"}, [10]={hint="Apporter 10 Pendentifs du Crépuscule au Garde d'argent Manados à Darnassus."}, [11]={hint="Apporter la Tête du Seigneur du crépuscule Kelris au Veilleur de l'aube Selgorm, à Darnassus."}, [12]={npc="Gershala Nightwhisper", tgt="Gershala Nightwhisper"}, [13]={npc="Garde d'argent Manados", tgt="Garde d'argent Manados"}, [14]={npc="Veilleur de l'aube Selgorm", tgt="Veilleur de l'aube Selgorm"}, [15]={npc="Gerrig Bonegrip", tgt="Gerrig Bonegrip"}}},
