    ["03-26"] = {name="Vallée de Strangleronce", steps={[1]={npc="Sven Yorgen", tgt="Sven Yorgen"}, [2]={npc="Sven Yorgen", tgt="Sven Yorgen", tag="Facultatif, Groupe recommandé"}, [3]={hint="Utiliser le Fléau de Morbent sur Morbent Fel, tuer Morbent Fel, puis rapporter le Fléau de Morbent à Sven, dans son camp.", tag="Facultatif, Groupe recommandé", desc="La suite est composée de quêtes élites. À faire seulement en groupe."}, [4]={npc="Sven Yorgen", tgt="Sven Yorgen", tag="Facultatif, Groupe recommandé"}, [5]={text="Depuis l'ouest du bois de la Pénombre, suis la route vers le sud jusqu'à la Vallée de Strangleronce et rends-toi d'abord au Camp des rebelles."}, [6]={npc="Soldat Thorsen", tgt="Soldat Thorsen", tag="Facultatif, Fais si tu le vois", desc="Il patrouille sur la route et ne donne la quête que si tu le sauves quand il tombe dans une embuscade; si tu ne le croises pas, passe-la."}, [7]={npc="Sergent Yohwa", tgt="Sergent Yohwa"}, [8]={npc="Sergent Yohwa", tgt="Sergent Yohwa"}, [9]={npc="Lieutenant Doren", tgt="Lieutenant Doren", tag="Facultatif"}, [10]={npc="Lieutenant Doren", tgt="Lieutenant Doren"}, [11]={npc="Barnil Stonepot", tgt="Barnil Stonepot"}, [12]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [13]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [14]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Facultatif", desc="Les pages tombent au hasard sur les monstres de Strangleronce. Achète celles qui manquent à l'hôtel des ventes et rends la quête une fois les quatre chapitres complets."}, [15]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Facultatif"}, [16]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Facultatif"}, [17]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Facultatif"}, [18]={npc="Barnil Stonepot", tgt="Barnil Stonepot", tag="Facultatif"}, [19]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [20]={npc="Sire S. J. Erlgadin", tgt="Sire S. J. Erlgadin"}, [21]={hint="Ajeck Rouack de l'Expédition Nesingwary veut que vous chassiez 10 Jeunes tigres de Strangleronce."}, [22]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [23]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [24]={hint="Le sire S. J. Erlgadin de l'Expédition Nesingwary veut que vous tuiez 10 Jeunes panthères."}, [25]={hint="Ajeck Rouack de l'Expédition Nesingwary veut que vous chassiez 10 Tigres de Strangleronce."}, [26]={hint="Tuer 15 Guerriers de la jungle."}, [27]={hint="Apporter 7 Remèdes tropicaux et 1 Extrait de fougère vénéneuse au sergentYohwa au Camp rebelle."}, [28]={npc="Archives d'Herod la Paperasse", npcObj=true, desc="Les dossiers dans la Base de Kurzen; la suite se trouve dans le même camp, prends-la si tu as le temps."}, [29]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [30]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [31]={npc="Sire S. J. Erlgadin", tgt="Sire S. J. Erlgadin"}, [32]={npc="Sire S. J. Erlgadin", tgt="Sire S. J. Erlgadin"}, [33]={hint="Le sire S. J. Erlgadin de l'Expédition Nesingwary veut que vous tuiez 10 Panthères."}, [34]={hint="Hemet Nesingwary veut que vous tuiez 10 Raptors de Strangleronce."}, [35]={hint="Ajeck Rouack de l'Expédition Nesingwary veut que vous chassiez 10 Anciens tigres de Strangleronce."}, [36]={npc="Sire S. J. Erlgadin", tgt="Sire S. J. Erlgadin"}, [37]={npc="Sire S. J. Erlgadin", tgt="Sire S. J. Erlgadin"}, [38]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [39]={npc="Ajeck Rouack", tgt="Ajeck Rouack"}, [40]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [41]={npc="Hemet Nesingwary", tgt="Hemet Nesingwary"}, [42]={npc="Sergent Yohwa", tgt="Sergent Yohwa"}, [43]={npc="Sergent Yohwa", tgt="Sergent Yohwa"}, [44]={npc="Caporal Kaleb", tgt="Caporal Kaleb"}, [45]={text="Suis la route de la Vallée de Strangleronce vers le sud jusqu'à Baie-du-Butin et reste loin du camp de la Horde en passant près de Grom'gol.", tag="Point de vol pas encore débloqué : la première fois, va-y à pied."}, [46]={npc="Krazek", tgt="Krazek"}, [47]={npc="Krazek", tgt="Krazek"}, [48]={npc="Baron Revilgaz", tgt="Baron Revi