    ["03-27"] = {steps={[1]={npc="Jennea Cannon", tgt="Jennea Cannon", tag="Tu peux déjà acheter à l'hôtel des ventes (ou te faire envoyer par un reroll) 1 × Jade (pour Les Objets de Puissance, plus tard dans le Marécage d'Âprefange).", desc="Rends-la à Tabetha au marécage d'Âprefange."}, [3]={npc="Elling Trias", tgt="Elling Trias"}, [4]={npc="Elling Trias", tgt="Elling Trias"}, [5]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [6]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [7]={hint="Battre Dashel Stonefist à Hurlevent."}, [8]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [9]={npc="Dashel Stonefist", tgt="Dashel Stonefist"}, [10]={npc="Elling Trias", tgt="Elling Trias"}, [11]={npc="Elling Trias", tgt="Elling Trias"}, [12]={text="Va au Quartier des Nains de Hurlevent et prends le tram des profondeurs pour Forgefer."}, [13]={npc="Maître-maçon Marblesten", tgt="Maître-maçon Marblesten"}, [14]={npc="Maître-maçon Marblesten", tgt="Maître-maçon Marblesten"}, [15]={npc="Roi Magni Bronzebeard", tgt="Roi Magni Bronzebeard"}, [16]={npc="Gerrig Bonegrip", tgt="Gerrig Bonegrip", tag="Facultatif", desc="Ne la rends que si tu as ramassé Livre : Les puissances d'en-bas à Sombrivage."}, [17]={npc="Grand Explorateur Magellas", tgt="Grand Explorateur Magellas"}, [18]={npc="Prospecteur Foudrepique", tgt="Prospecteur Foudrepique"}, [19]={npc="Prospecteur Foudrepique", tgt="Prospecteur Foudrepique"}, [20]={npc="Prospecteur Foudrepique", tgt="Prospecteur Foudrepique"}, [21]={npc="Prospecteur Foudrepique", tgt="Prospecteur Foudrepique"}, [22]={npc="Lago Blackwrench", tgt="Lago Blackwrench"}, [23]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Vole de Forgefer à Baie-du-Butin (avec escale à Hurlevent), puis prends le bateau pour Cabestan."}, [24]={npc="Strahad Farsan", tgt="Strahad Farsan"}, [25]={npc="Krom Stoutarm", tgt="Krom Stoutarm", desc="Prends le bateau de Cabestan à Baie-du-Butin, puis vole vers Forgefer."}, [26]={npc="Krom Stoutarm", tgt="Krom Stoutarm"}, [27]={hint="Retrouver le Tome moisi et le Manuscrit en lambeaux pour Krom Stoutarm à Forgefer.", desc="Vole de Forgefer à Austrivage, et reviens à Forgefer au retour."}, [28]={npc="Krom Stoutarm", tgt="Krom Stoutarm"}, [29]={npc="Krom Stoutarm", tgt="Krom Stoutarm"}, [30]={hint="Apporter le Tome recomposé et 3 Bâtonnet de canalisation à Strahad Farsan à Ratchet.", desc="Vole de Forgefer à Port de Menethil pour la partie des Paluns."}, [31]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Prends le bateau du quai sud de Port de Menethil à Theramore, débloque son point de vol, puis vole vers Cabestan. Ou vole de Port de Menethil à Baie-du-Butin (avec escales à Forgefer et Hurlevent) et prends le bateau de là."}, [32]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Invoque et vaincs le chasseur corrompu sur le cercle près de Strahad Farsan."}, [33]={hint="Utiliser le Tome de la Cabale pour invoquer et soumettre un Chasseur corrompu, puis rapporter le Tome de la Cabale à Strahad Farsan, à Ratchet.", desc="Invoque et vaincs le chasseur corrompu sur le cercle près de Strahad Farsan."}, [34]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Invoque et vaincs le chasseur corrompu sur le cercle près de Strahad Farsan."}, [35]={text="Depuis Cabestan, suis la route des Tarides vers le nord, continue vers le nord après La Croisée pour entrer en Orneval, puis suis la route d'Orneval vers l'ouest jusqu'à Astranaar (34.41, 47.99).", desc="La Croisée et le Poste de Bois-brisé sont des bases de la Horde : contourne-les. Si Theramore est sur ta carte des vols, tu peux voler directement jusqu'à Astranaar (avec escale à Theramore et à Auberdine)."}, [36]={npc="Klockmort Spannerspan", tgt="Klockmort Spannerspan"}, [37]={npc="Eldrun Brise-tempête", tgt="Eldrun Brise-tempête", desc="Appel de l'air : trouve Veyric Hametonne dans les Hautes-terres Arathies."}, [38]={to="Menethil Harbor", toA="{a:150}"}, [39]={npc="Mikhail", tgt="Mikhail"}, [40]={npc="Mikhail", tgt="Mikhail"}, [41]={hint="Soumettre Tapoke Jahn avant qu'il ne s'échappe et ensuite retourner voir Mikhail à Menethil."}, [42]={npc="Mikhail", tgt="Mikhail"}, [43]={npc="Tapoke Slim Jahn", tgt="Tapoke Slim Jahn"}, [44]={npc="Mikhail", tgt="Mikhail"}, [45]={npc="Mikhail", tgt="Mikhail"}, [46]={npc="Vincent Hyal", tgt="Vincent Hyal", desc="Dans la même auberge; porte la lettre à Theramore."}, [47]={to="Auberdine", from="Menethil Harbor", fromA="{a:150}", desc="Ce bateau fait escale à Austrivage. Descends à Auberdine."}}},
    ["03-28"] = {steps={[1]={to="Astranaar", toA="{a:415}"}, [2]={npc="Sentinelle Melyria Frostshadow", tgt="Sentinelle Melyria Frostshadow"}, [3]={npc="Illiyana", tgt="Illiyana"}, [4]={npc="Pelturas Whitemoon", tgt="Pelturas Whitemoon"}, [5]={text="Suis la route jusqu'à ce point."}, [6]={text="Suis la route jusqu'à ce point."}, [7]={hint="Se rendre au Val hurlant et étudier le « Tome de Mel'Thandris », puis retourner voir la Sentinelle Melyria Frostshadow au Sanctuaire d'Aessina.", desc="Entre dans la grotte pour prendre le livre. On attire facilement trop de monstres, et c'est plus dur quand le rare est là."}, [8]={text="Suis la route jusqu'à ce point."}, [9]={hint="Reprendre une Pierre de lune tombée à l'Oracle Sombretaillis puis l'apporter à Pelturas Whitemoon à Astranaar."}, [10]={text="Suis la route jusqu'à ce point."}, [11]={hint="Libérer les Âmes de Bien-nés captives au défilé de la Nuit et à Satyrnaar, puis retourner voir Delgren le Purificateur au poste de Maestra."}, [12]={npc="Anilia", tgt="Anilia"}, [13]={npc="Anilia", tgt="Anilia"}, [14]={hint="Tuer Geltharis et rendre la Branche de Cénarius à Illiyana au Sanctuaire d'Aessina."}, [15]={npc="Kayneth Stillwind", tgt="Kayneth Stillwind"}, [16]={npc="Maseara Lune-d'Automne", tgt="Maseara Lune-d'Automne"}, [17]={hint="Maseara Lune-d'Automne vous demande de fouiller la région située à l'ouest du Chant des forêts, parmi les démons de Satyrnaar. À votre retour, faites-lui part de tout indice concernant son époux, Kurothel."}, [18]={npc="Maseara Lune-d'Automne", tgt="Maseara Lune-d'Automne"}, [19]={nodeA="{a:3137}", node="Talrendis Point", desc="Depuis Chant des forêts, suis la route vers l'est jusqu'en Azshara; le camp est juste à côté de l'entrée."}, [20]={to="Astranaar", toA="{a:415}"}, [21]={npc="Pelturas Whitemoon", tgt="Pelturas Whitemoon"}, [22]={npc="Sentinelle Melyria Frostshadow", tgt="Sentinelle Melyria Frostshadow"}, [23]={npc="Sentinelle Melyria Frostshadow", tgt="Sentinelle Melyria Frostshadow", tag="Facultatif"}, [24]={npc="Illiyana", tgt="Illiyana"}, [25]={npc="Delgren le Purificateur", tgt="Delgren le Purificateur"}}},
    ["03-29"] = {grind={[1]={mob="Contemplateur du sel gemme", note="Extrémité sud des Salines; monstres normaux, dans la même zone que les basilics de la quête Les cahots de la piste."}, [2]={mob="Peau de cristal du sel gemme", note="Mêlés aux Contemplateurs; plus nombreux, niveau légèrement inférieur."}}, steps={[1]={to="Rut'theran Village", toA="{a:702}", tag="Facultatif", desc="Peu d'XP dans la partie Darnassus. Ignore si tu es pressé."}, [2]={text="Prends le portail de Rut'theran pour Darnassus.", tag="Facultatif"}, [3]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Facultatif"}, [4]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Facultatif"}, [5]={hint="Fouiller le coffre de Velinde pour trouver son Journal et le rendre ensuite avec la clé à Thyn'tel Bladeweaver à Darnassus.", tag="Facultatif"}, [6]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Facultatif"}, [7]={npc="Thyn'tel Bladeweaver", tgt="Thyn'tel Bladeweaver", tag="Facultatif"}, [8]={text="Prends le portail de Darnassus pour retourner à Rut'theran.", tag="Facultatif"}, [9]={text="Si tu as fait les quêtes optionnelles de Darnassus, vole de Rut'theran à Cabestan (avec escales à Auberdine et à la Halte de Talrendis); si tu les as passées, vole depuis Astranaar (avec escale à la Halte de Talrendis). Suis la route principale vers le sud, contourne le Camp Taurajo et prends la Grande élévation pour descendre à Mille pointes. Ne passe par le Rempart de Mor'shan que si aucun des deux points n'est débloqué."}, [10]={text="Suis la route jusqu'à ce point."}, [11]={nodeA="{a:489}", node="Thalanaar"}, [12]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [13]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [14]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [15]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [16]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [17]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [18]={npc="Pozzik", tgt="Pozzik"}, [19]={npc="Maître pisteur Zherin", tgt="Maître pisteur Zherin"}, [20]={hint="Se procurer 10 Os creux de vautour pour Pozzik dans les Salines."}, [21]={hint="Tuer 10 Basilics du sel gemme, 10 Peaux de cristal du sel gemme et 10 Contemplateurs du sel gemme pour le maître pisteur Zherin des Salines."}, [22]={hint="Apporter 9 Carapaces de tortue durcies à Wizzle Brassbolts dans les Salines."}, [23]={hint="Apporter 30 Pièces de Chariot explosif à Kravel Koalbeard des Salines."}, [24]={hint="Apportez 6 doses de Venin de scorpide acide à Fizzle Brassbolts, dans les Salines."}, [25]={npc="Pozzik", tgt="Pozzik"}, [26]={npc="Maître pisteur Zherin", tgt="Maître pisteur Zherin"}, [27]={npc="Wizzle Brassbolts", tgt="Wizzle Brassbolts"}, [28]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [29]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [30]={desc="Si tu n'es pas encore niveau 35 avant de quitter les Salines, monte au niveau 35 en tuant des Contemplateurs du sel gemme et des Peaux de cristal du sel gemme au sud de la piste de course."}, [31]={text="Depuis les Salines, suis la route vers le sud jusqu'à Tanaris, débloque le point de vol de Gadgetzan, puis utilise ta pierre de foyer.", tag="Point de vol pas encore débloqué : la première fois, va-y à pied."}, [32]={nodeA="{a:976}", node="Gadgetzan"}, [33]={}}},
    ["03-30"] = {name="Hautes-terres d'Arathi", grind={[1]={mob="Kobold Sèche-moustache", note="Aux abords de l'entrée de la Gorge des Sèches-moustaches; monstres normaux, juste à côté de l'endroit où tu termines La Princesse emprisonnée."}, [2]={mob="Terrassier Sèche-moustache", note="Près du cristal, au fond de la gorge; niveau mieux adapté."}, [3]={mob="Brute Rochepoing", note="Les ogres autour du Hall Rochepoing; sur ton chemin quand tu vas chercher la baguette."}, [4]={mob="Chasseur des ombres Witherbark", note="Fanécorce, au sud-est; les mêmes trolls que pour Valoir son poids en or."}}, steps={[1]={to="Refuge Pointe", toA="{a:320}", desc="Si le Refuge de l'Ornière n'est pas débloqué, vole jusqu'au Port de Menethil, suis la route vers le nord-est à travers Les Paluns, franchis le Viaduc de Thandol pour entrer dans les Hautes-terres Arathies, puis suis la route jusqu'au Refuge de l'Ornière."}, [2]={npc="Capitaine Nials", tgt="Capitaine Nials"}, [3]={npc="Tableau des recherches", npcObj=true, tag="Groupe recommandé, Facultatif"}, [4]={npc="Tableau des recherches", npcObj=true, tag="Groupe recommandé, Facultatif", desc="Otto et Falconcrest sont des élites de niveau 38 et 40."}, [5]={npc="Skuerto", tgt="Skuerto"}, [6]={npc="Apprenti Kryten", tgt="Apprenti Kryten"}, [7]={npc="Fragments de Myzrael", npcObj=true}, [8]={hint="Collecter 12 Poussières de Myzrael, puis les répandre sur les Eclats iridescents, à la gorge des Sèches-moustaches."}, [9]={npc="Fragments iridescents", npcObj=true}, [10]={desc="Monte jusqu'à environ trois quarts du niveau 36; tue des Kobolds Sèche-moustache et des Terrassiers Sèche-moustache ici même, dans la Gorge des Sèches-moustaches."}, [11]={npc="Fragments iridescents", npcObj=true, desc="La Pierre de Lien orientale est sur ton chemin vers l'ouest, prends-la d'abord; prends la Pierre de Lien extérieure en allant au Refuge de l'Ornière."}, [12]={npc="Quae", tgt="Quae"}, [13]={npc="Quae", tgt="Quae"}, [14]={hint="Trouver la Messagère des Réprouvés et ramener ses documents scellés à Quae près de la Ferme des Go'shek.", desc="La Messagère des Réprouvés patrouille sur la route aux alentours de la Ferme de Go'Shek; tue-la dès que tu la vois et prends les Documents scellés."}, [15]={hint="Trouver 10 Défenses de Witherbark, 4 Bourses-médecine Witherbark et un Couteau de Chasseur d'ombre pour l'Apprenti Kryten au Refuge de l'Ornière.", desc="Attention à la Messagère des Réprouvés qui patrouille."}, [16]={npc="Apprenti Kryten", tgt="Apprenti Kryten"}, [17]={npc="Capitaine Nials", tgt="Capitaine Nials", desc="Rends la quête à Demar Brant à Fort-Lointain, dans Rives Claires; tu y vas à la prochaine étape."}, [18]={npc="Skuerto", tgt="Skuerto"}, [19]={desc="Si tu n'es pas encore niveau 37 avant d'affronter Kor'gresh Coldrage (niveau 39), tue des Brutes Rochepoing devant le Hall Rochepoing, ou va à Fânécorce, à l'est, tuer des trolls Fânécorce jusqu'au niveau 37."}, [20]={hint="Trouver la Baguette d'invocation de Trelane et revenir voir Skuerto au Refuge de l'Ornière."}, [21]={npc="Quae", tgt="Quae"}, [22]={npc="Quae", tgt="Quae"}, [23]={npc="Kinelory", tgt="Kinelory"}, [24]={npc="Kinelory", tgt="Kinelory"}, [25]={hint="Protéger Kinelory jusqu'à ce qu'elle rejoigne Quae.", desc="Quête d'escorte : suis Kinelory; il y aura des embuscades en chemin."}, [26]={npc="Quae", tgt="Quae"}, [27]={npc="Quae", tgt="Quae"}, [28]={npc="Skuerto", tgt="Skuerto"}, [29]={npc="Skuerto", tgt="Skuerto", tag="Groupe recommandé, Facultatif"}, [30]={hint="Collecter la Clé ardente, la Clé armoriée et la Clé de tonnerre aux lieux suivants : la Pierre de lien occidentale, la Pierre de lien orientale et la Pierre de lien extérieure."}, [31]={hint="Tuer 10 Malandrins du Syndicat et 6 Mercenaires du Syndicat."}, [32]={npc="Capitaine Nials", tgt="Capitaine Nials"}, [33]={npc="Capitaine Nials", tgt="Capitaine Nials", tag="Groupe recommandé, Facultatif"}, [34]={npc="Pierre de Lien Intérieure", npcObj=true}, [35]={hint="Apporter la tête de Marez au capitaine Nials, au Refuge de l'Ornière.", tag="Groupe recommandé, Facultatif"}, [36]={hint="Apporter les Têtes de Falconcrest et d'Otto au capitaine Nials au Refuge de l'Ornière.", tag="Groupe recommandé, Facultatif"}, [37]={hint="Rapporter les Insignes de Stromgarde au capitaine Nials au Refuge de l'Ornière.", tag="Groupe recommandé, Facultatif"}, [38]={hint="Trouver une Agate d'azur et la porter à l'Apprenti Kryten au Refuge de l'Ornière.", tag="Groupe recommandé, Facultatif"}, [39]={npc="Capitaine Nials", tgt="Capitaine Nials", tag="Groupe recommandé, Facultatif"}, [40]={npc="Capitaine Nials", tgt="Capitaine Nials", tag="Groupe recommandé, Facultatif"}, [41]={npc="Capitaine Nials", tgt="Capitaine Nials", tag="Groupe recommandé, Facultatif"}, [42]={npc="Apprenti Kryten", tgt="Apprenti Kryten", tag="Groupe recommandé, Facultatif"}, [43]={npc="Apprenti Kryten", tgt="Apprenti Kryten"}, [44]={npc="Skuerto", tgt="Skuerto"}, [45]={npc="Skuerto", tgt="Skuerto"}, [46]={hint="Trouver le Phylactère de Trelane, l'Orbe de Trelane et l'Agathe d'ambre de Trelane. Les rapporter à Skuerto au Refuge de l'Ornière.", tag="À faire plus tard en passant"}, [47]={npc="Skuerto", tgt="Skuerto"}, [48]={npc="Skuerto", tgt="Skuerto"}, [49]={hint="Volez un uniforme du Syndicat au manoir de Nordclos afin d'infiltrer le donjon de Stromgarde.", desc="Vole un uniforme du Syndicat au manoir de Nordclos, dans les Hautes-terres Arathies."}, [50]={npc="Cantine du Syndicat", npcObj=true}, [51]={npc="Cantine du Syndicat", npcObj=true}, [52]={hint="Portez le déguisement d'un membre du Syndicat, puis trouvez quelqu'un qui soit au courant de la transaction secrète au donjon de Stromgarde."}, [53]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [54]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [55]={hint="Dans le donjon de Stromgarde, trouvez de quoi convaincre Anastasia de vous révéler les détails de cette transaction secrète."}, [56]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [57]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [58]={hint="Interrompez la transaction secrète et récupérez l'objet destiné au Syndicat. Rapportez-le ensuite à Myrokos Sourdeforme, au manoir de Ravenholdt."}, [59]={npc="Myrokos Silentform", tgt="Myrokos Silentform"}, [60]={npc="Veyric Hametonne", tgt="Veyric Hametonne"}, [61]={npc="Veyric Hametonne", tgt="Veyric Hametonne", tag="Groupe recommandé, Facultatif", desc="Il faut faire le Kraal de Tranchebauge (le donjon au sud des Tarides); fais-la une fois que tu as un groupe; passe aussi la suite, Tempête, terre et feu."}, [62]={hint="Éliminez Charlga Trancheflanc au kraal de Tranchebauge et recueillez des renseignements sur les plans des Hurans.", tag="Groupe recommandé, Facultatif"}, [63]={npc="Veyric Hametonne", tgt="Veyric Hametonne", tag="Groupe recommandé, Facultatif", desc="Tu peux aussi trouver Veyric Hametonne à Forgefer (47.10, 13.79)."}, [64]={npc="Veyric Hametonne", tgt="Veyric Hametonne", tag="Facultatif", desc="Les quatre types de totems tordus tombent sur les monstres du Marécage d'Âprefange, des Terres ingrates, du Marais des Chagrins et de Désolace; ramasse-les en chemin au fil des prochaines étapes; pour finir, rends la quête à Veyric Hametonne à Forgefer."}, [65]={to="Southshore", toA="{a:271}"}, [66]={npc="Phin Odelic", tgt="Phin Odelic"}, [67]={npc="Magistrat Henry Maleb", tgt="Magistrat Henry Maleb"}, [68]={desc="Si ta pierre de foyer est en recharge, vole d'Austrivage à Forgefer et reprends le tram des profondeurs pour Hurlevent."}}},
    ["05-d8"] = {name="Monastère écarlate", entrance="Clairières de Tirisfal 82.60, 33.80", pickup="Prends les quêtes du donjon dès ton passage : Les Paluns (2e visite). Inutile de revenir exprès avant le donjon.", pickupS={{"Prends les quêtes du donjon dès ton passage : Les Paluns (2e visite)"}, {"Inutile de revenir exprès avant le donjon"}}, steps={[1]={npc="Bibliothécaire Mae Paledust", tgt="Bibliothécaire Mae Paledust"}, [2]={to="Southshore", toA="{a:271}", desc="Tu feras une correspondance à Forgefer."}, [3]={npc="Raleigh le Dévot", tgt="Raleigh le Dévot", tag="Facultatif"}, [4]={npc="Raleigh le Dévot", tgt="Raleigh le Dévot", tag="Facultatif, Groupe recommandé"}, [5]={npc="Magus Olvek", tgt="Magus Olvek", tag="Facultatif"}, [6]={text="Depuis Hautebrande, va vers l'ouest dans la forêt des Pins-Argentés, puis suis la route principale vers le nord jusqu'à Tirisfal. Contourne les gardes du Sépulcre, de Fossoyeuse et de Brill, puis rejoins le Monastère écarlate au nord-est."}, [7]={text="Entrée : Monastère écarlate"}, [8]={hint="Reprendre « la Mythologie des Titans » au Monastère et le rapporter au Bibliothécaire Mae Paledust à Forgefer.", desc="Lieu : Étagère au fond de la bibliothèque.", spot="Étagère au fond de la bibliothèque."}, [9]={hint="Récupérez La Magie perdue des maîtres des runes au monastère Écarlate.", tag="Facultatif"}, [10]={hint="Tuer le grand inquisiteur Whitemane, le commandant Mograine de la Croisade, le champion Herod de la Croisade et le maître-chien Loksey, et retourner faire un rapport à Raleigh le Dévot à Austrivage.", tag="Facultatif", desc="Battez Loksey dans la bibliothèque, Herod dans l'armurerie, puis Mograine et Whitemane dans la cathédrale. Vous pouvez faire les ailes en plusieurs visites."}, [11]={npc="Magus Olvek", tgt="Magus Olvek", tag="Facultatif"}, [12]={npc="Raleigh le Dévot", tgt="Raleigh le Dévot", tag="Facultatif, Nécessite du matériel"}, [13]={npc="Bibliothécaire Mae Paledust", tgt="Bibliothécaire Mae Paledust", tag="Facultatif", desc="Revenez à Austrivage par Tirisfal et la forêt des Pins argentés. Prenez un vol pour Forgefer si la liaison est disponible. Sinon, prenez le bateau pour le port de Menethil, suivez la route de montagne au sud des Paluns vers le Loch Modan, puis traversez le tunnel vers Dun Morogh et poursuivez jusqu'à Forgefer. Si votre pierre de foyer est prête et liée à Hurlevent, vous pouvez y retourner et prendre le Tram des profondeurs."}}},
    ["03-31"] = {tips={{k="提醒", text="Rog'mar, au centre de la carte, est une ville de la Horde; n'approche pas.", s={{"Rog'mar, au centre de la carte, est une ville de la Horde; n'approche pas"}}}}, steps={[1]={to="Lakeshire", toA="{a:69}", tag="Avant de partir pour Rives Claires, tu peux acheter à l'hôtel des ventes (ou te faire envoyer par un reroll) 8 × Pierre à aiguiser solide (pour Des lames des plus affûtées).", desc="Fort-Lointain n'a pas encore de point de vol : à la première visite, va vers l'est par la route depuis Comté-du-Lac jusqu'à l'entrée ouest de Rives Claires."}, [2]={npc="Dorin Songblade", tgt="Dorin Songblade", tag="Facultatif, Groupe recommandé"}, [3]={text="Passé l'entrée à l'est des Carmines, on arrive aux collines Hirsutes; les gnolls de niveau 36-38 près de l'entrée frappent fort.", tag="Point de vol pas encore débloqué : la première fois, va-y à pied."}, [4]={npc="Eclaireur Bolain", tgt="Eclaireur Bolain"}, [5]={npc="Cédric Dalton", tgt="Cédric Dalton"}, [6]={npc="Cédric Dalton", tgt="Cédric Dalton"}, [7]={npc="Cédric Dalton", tgt="Cédric Dalton"}, [8]={npc="Cédric Dalton", tgt="Cédric Dalton", tag="Facultatif, Groupe recommandé", desc="Snargl est un élite de niveau 40; si tu ne peux pas le vaincre, passe-le."}, [9]={npc="Kurty", tgt="Kurty"}, [10]={npc="Halligan Turner", tgt="Halligan Turner"}, [11]={npc="Halligan Turner", tgt="Halligan Turner"}, [12]={npc="Hurley", tgt="Hurley"}, [13]={npc="Hurley", tgt="Hurley"}, [14]={hint="Partez avec Hurley pour aider Kurty.", desc="Suis Hurley pour sauver Kurty."}, [15]={hint="Tuez 8 mystiques des Carmines, 8 trappeurs des Carmines et 6 brutes des Carmines pour Cédric Dalton, à la garde du Sud."}, [16]={hint="Récupérez 8 lames de scie dans les camps de Gnolls des collines Hirsutes pour Halligan Turner, à la scierie.", desc="Les lames de scie sont éparpillées sur le sol du camp des gnolls."}, [17]={hint="Repérez Snargl dans les collines Hirsutes, tuez-le et apportez son museau à Cédric Dalton, à la garde du Sud.", tag="Facultatif, Groupe recommandé", desc="Snargl est un élite de niveau 40; si tu ne peux pas le vaincre, passe-le."}, [18]={npc="Halligan Turner", tgt="Halligan Turner"}, [19]={npc="Halligan Turner", tgt="Halligan Turner"}, [20]={npc="Eleanor Holmsby", tgt="Eleanor Holmsby"}, [21]={npc="Robbie Holmsby", tgt="Robbie Holmsby"}, [22]={npc="Gardien Fredericks", tgt="Gardien Fredericks"}, [23]={npc="Cédric Dalton", tgt="Cédric Dalton"}, [24]={npc="Cédric Dalton", tgt="Cédric Dalton", tag="Facultatif"}, [25]={npc="Benjy Charron", tgt="Benjy Charron"}, [26]={hint="Tuez 8 oracles aileron-fangeux et 8 guerriers aileron-fangeux le long de la rivière à proximité de la grange des Charron."}, [27]={hint="Rassemblez 4 carapaces d'écrevisse géante, 4 parts de purin frais et 8 têtes de Murlocs aileron-fangeux pour Halligan Turner.", desc="Tue les têtes de murlocs Vasemuche avec les démons d'eau douce, puis va au nord tuer les écrevisses géantes et ramasser le fumier frais."}, [28]={hint="Trouvez le chapeau de Robbie au bord de la rivière, près des Murlocs.", desc="Trouve le chapeau dans le camp des murlocs Vasemuche."}, [29]={nodeA="{a:16724}", node="Farholde Keep"}, [30]={npc="Demar Brant", tgt="Demar Brant"}, [31]={npc="Demar Brant", tgt="Demar Brant"}, [32]={npc="Demar Brant", tgt="Demar Brant"}, [33]={npc="Demar Brant", tgt="Demar Brant"}, [34]={npc="Ashe Ambrehall", tgt="Ashe Ambrehall"}, [35]={npc="Ashe Ambrehall", tgt="Ashe Ambrehall"}, [36]={npc="Amber Murmelame", tgt="Amber Murmelame"}, [37]={npc="Soeur Rolande", tgt="Soeur Rolande"}, [38]={npc="Bertrand Front-de-fer", tgt="Bertrand Front-de-fer"}, [39]={npc="Cassandra Charron", tgt="Cassandra Charron"}, [40]={hint="Tuez 5 chauves-souris de la pénombre nichées dans la cathédrale de Fort-Lointain pour sœur Rolande."}, [41]={npc="Soeur Rolande", tgt="Soeur Rolande"}, [42]={npc="Soeur Rolande", tgt="Soeur Rolande", tag="Facultatif, Nécessite du matériel", desc="Il faut 5 bougies sanctifiées, vendues par les marchands de composants. Si tu n'en as pas, passe cette quête et la suivante."}, [43]={npc="Soeur Rolande", tgt="Soeur Rolande", tag="Facultatif"}, [44]={npc="Soeur Rolande", tgt="Soeur Rolande"}, [45]={hint="Déposez 3 bougies mémorielles sur les tombes du cimetière de la chapelle pour sœur Rolande, au donjon de Fort-Lointain.", desc="La tombe est à côté de la chapelle de Fort-Lointain."}, [46]={npc="Soeur Rolande", tgt="Soeur Rolande"}, [47]={hint="Récupérez 3 ballots de foin pour Amber, au terrain d'entraînement.", desc="Les bottes de foin sont dans les champs près de Fort-Lointain."}, [48]={npc="Amber Murmelame", tgt="Amber Murmelame"}, [49]={npc="Amber Murmelame", tgt="Amber Murmelame", tag="Facultatif, Nécessite du matériel", desc="Il faut 8 × Pierre à aiguiser solide. Achète-les à l'hôtel des ventes ou demande à un forgeron. Passe si tu ne les as pas sur toi."}, [50]={npc="Amber Murmelame", tgt="Amber Murmelame", tag="Facultatif"}, [51]={npc="Benjy Charron", tgt="Benjy Charron"}, [52]={npc="Benjy Charron", tgt="Benjy Charron"}, [53]={npc="Benjy Charron", tgt="Benjy Charron"}, [54]={hint="Cherchez des indices concernant la disparition des chevaux près des écuries de la grange des Charron.", desc="Cherche des preuves autour des enclos de la ferme."}, [55]={npc="Benjy Charron", tgt="Benjy Charron"}, [56]={npc="Benjy Charron", tgt="Benjy Charron"}, [57]={npc="Benjy Charron", tgt="Benjy Charron"}, [58]={hint="Tuez le coyote nommé Fourre-Suie et rapportez sa fourrure à Benjy Charron."}, [59]={hint="Trouvez l'un des chevaux qui ont fui la grange des Charron après l'attaque des coyotes et donnez-lui un peu de fourrage.", desc="Le cheval égaré est près de la ferme."}, [60]={npc="Cheval perdu", tgt="Cheval perdu"}, [61]={npc="Cheval perdu", tgt="Cheval perdu"}, [62]={hint="Ramenez le cheval perdu à la grange des Charron.", desc="Ramène le cheval égaré à la ferme."}, [63]={npc="Benjy Charron", tgt="Benjy Charron"}, [64]={npc="Benjy Charron", tgt="Benjy Charron"}, [65]={npc="Robbie Holmsby", tgt="Robbie Holmsby"}, [66]={npc="Halligan Turner", tgt="Halligan Turner"}, [67]={npc="Halligan Turner", tgt="Halligan Turner"}, [68]={npc="Halligan Turner", tgt="Halligan Turner"}, [69]={hint="Plantez 5 arbrisseaux autour du camp de bûcherons grâce au kit de plantation de Halligan Turner."}, [70]={npc="Halligan Turner", tgt="Halligan Turner"}, [71]={hint="Retrouvez la caisse de contremaître à Bertrand Front-de-fer, et rapportez-la-lui au donjon de Fort-Lointain.", desc="La caisse du contremaître est au camp de bûcherons de Turner."}, [72]={npc="Fermier Elbrim", tgt="Fermier Elbrim"}, [73]={npc="Fuzzle", tgt="Fuzzle"}, [74]={hint="Terrassez 8 écumeurs du Crépuscule, 8 ténébromanciens du Crépuscule et 8 néophytes du Crépuscule à Clairsoleil, pour Demar Brant."}, [75]={hint="Récupérez 5 souvenirs des fermiers sur les écumeurs du Crépuscule et déposez-les sur les tombes à l'ouest de la ferme d'Elbrim.", desc="Tue des Ecumeurs du Crépuscule pour les souvenirs, puis dépose-les sur les tombes à l'ouest de la ferme d'Elbrim."}, [76]={hint="Récupérez 25 charmes du Crépuscule sur les ténébromanciens du Crépuscule et sur les néophytes du Crépuscule à Clairsoleil pour Ashe Ambrehall, au donjon de Fort-Lointain."}, [77]={hint="Récupérez 5 pages du Crépuscule à Clairsoleil pour Ashe Ambrehall, au donjon de Fort-Lointain.", desc="Les pages du Crépuscule sont éparpillées dans Clairsoleil."}, [78]={npc="Registre du grand maréchal", npcObj=true, tag="Si l'objet tombe, Facultatif", desc="Les monstres du Crépuscule laissent tomber le registre du grand maréchal; fais un clic droit dessus dans ton sac pour lancer la quête."}, [79]={hint="Apportez 20 os de doigt du Crépuscule à Fuzzle.", desc="Les os de doigt du Crépuscule viennent des mêmes monstres du Crépuscule que pour Sauver Clairsoleil."}, [80]={npc="Fuzzle", tgt="Fuzzle"}, [81]={npc="Fuzzle", tgt="Fuzzle", desc="Suis Fuzzle pendant sa fuite. À l'arrivée, il se retourne contre toi avec 2 gnolls; bats-les, puis v