    ["03-32"] = {steps={[1]={to="Menethil Harbor", toA="{a:150}", desc="Tu feras escale à Thelsamar."}, [2]={to="Theramore", from="Menethil Harbor", fromA="{a:150}", desc="Embarque au quai sud du Port de Menethil."}, [3]={node="Theramore"}, [4]={to="Ratchet", toA="{a:392}"}, [5]={npc="Maître des quais Dizzywig", tgt="Maître des quais Dizzywig"}, [6]={npc="Maître des quais Dizzywig", tgt="Maître des quais Dizzywig"}, [7]={npc="Maître des quais Dizzywig", tgt="Maître des quais Dizzywig", tag="Facultatif"}, [8]={to="Gadgetzan", toA="{a:976}", desc="Tu feras escale à Theramore. Si tu n'as pas débloqué Gadgetzan à {s:03-29}, va de Cabestan vers le sud-ouest à travers Les Tarides, prends la Grande élévation pour descendre à Mille pointes, puis va vers l'est jusqu'aux Salines."}, [9]={text="Depuis Gadgetzan, suis la route vers le nord jusqu'à Salines, dans Mille pointes."}, [10]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [11]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [12]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [13]={npc="Fizzle Brassbolts", tgt="Fizzle Brassbolts"}, [14]={npc="Kravel Koalbeard", tgt="Kravel Koalbeard"}, [15]={text="Suis la route jusqu'à ce point."}, [16]={to="Theramore"}, [17]={text="Epices apaisantes"}, [18]={npc="Garde Byron", tgt="Garde Byron"}, [19]={npc="Capitaine Garran Vimaire", tgt="Capitaine Garran Vimaire"}, [20]={npc="Commandant Samaul", tgt="Commandant Samaul"}, [21]={npc="Commandant Samaul", tgt="Commandant Samaul"}, [22]={npc="Tabetha", tgt="Tabetha"}, [23]={npc="Tabetha", tgt="Tabetha"}, [24]={npc="Magus Tirth", tgt="Magus Tirth"}, [25]={npc="Magus Tirth", tgt="Magus Tirth"}, [26]={hint="Trouver l'Incantation pour ouvrir le coffre-fort de Tirth puis retourner voir Tirth."}, [27]={npc="Magus Tirth", tgt="Magus Tirth"}, [28]={npc="Magus Tirth", tgt="Magus Tirth", tag="Groupe recommandé, Facultatif", desc="Le livre est dans la bibliothèque du Monastère écarlate; fais-la une fois que tu as un groupe; La baguette du ma