    ["03-35"] = {grind={[1]={mob="Coyote farouche des rochers", note="Les terres arides au sud du camp; monstres normaux dispersés, à tuer un par un."}, [2]={mob="Briseur d'os Cavepierre", note="Au sud de la Fin d'Agmond; niveau mieux adapté. Quand ils sont en groupe, attire-les depuis l'extérieur."}}, steps={[1]={npc="Jennea Cannon", tgt="Jennea Cannon", desc="Rends-la à Tabetha au marécage d'Âprefange."}, [2]={npc="Archimage Malin", tgt="Archimage Malin"}, [3]={npc="Brohann Caskbelly", tgt="Brohann Caskbelly"}, [4]={npc="Grand sorcier Andromath", tgt="Grand sorcier Andromath"}, [5]={to="Thelsamar", toA="{a:144}"}, [6]={npc="Ghak Healtouch", tgt="Ghak Healtouch"}, [7]={npc="Prospecteur Ironband", tgt="Prospecteur Ironband"}, [8]={npc="Prospecteur Ironband", tgt="Prospecteur Ironband"}, [9]={text="Depuis la route du sud de Loch Modan, sors du col vers le sud pour entrer dans les Terres ingrates et suis la route vers le sud jusqu'au site de fouilles.", tag="Il n'y a pas de point de vol de l'Alliance dans les Terres ingrates."}, [10]={npc="Prospecteur Ryedol", tgt="Prospecteur Ryedol", desc="Désormais, tue tous les busards et loups que tu vois : une quête en a besoin."}, [11]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew"}, [12]={npc="Martek l'Exilé", tgt="Martek l'Exilé"}, [13]={npc="Martek l'Exilé", tgt="Martek l'Exilé"}, [14]={npc="Rigglefuzz", tgt="Rigglefuzz"}, [15]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [16]={hint="Trouver 10 Petits Eclats de Pierre et les porter à Lotwil Veriatus dans les Terres ingrates."}, [17]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [18]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [19]={hint="Apporter 3 Grands blocs de pierre à Lotwil Veriatus dans les Terres ingrates."}, [20]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [21]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus", tag="Si tu peux affronter des monstres de haut niveau, Facultatif"}, [22]={hint="Retrouver la Caisse de fournitures pour Sigrun Ironhew."}, [23]={hint="Trouver le Piolet de chance de Ryedol et le rapporter au Prospecteur Ryedol au sud du site de fouilles de Hammertoe."}, [24]={npc="Carte chiffonnée", npcObj=true}, [25]={npc="Prospecteur Ryedol", tgt="Prospecteur Ryedol"}, [26]={npc="Prospecteur Ryedol", tgt="Prospecteur Ryedol"}, [27]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew"}, [28]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew"}, [29]={desc="Si tu n'es pas encore niveau 40, monte au niveau 40 en tuant des Coyotes farouches des rochers au sud du camp, ou des Briseurs d'os Cavepierre plus au sud, dans la zone des Cavepierre."}, [30]={npc="Garek", tgt="Garek"}, [31]={npc="Squelette de nain décrépi", npcObj=true, desc="Attention au Boss Tho'grun qui patrouille."}, [32]={npc="Squelette de nain décrépi", npcObj=true}, [33]={hint="Tuer l'assassin d'Agmond : Murdaloc."}, [34]={hint="Apporter 10 Flocons d'indurium à Martek l'Exilé dans les Terres ingrates."}, [35]={hint="Apporter 5 Brassards de liaison de pierre à Lotwil Veriatus dans les Terres ingrates.", tag="Si tu peux affronter des monstres de haut niveau, Facultatif", desc="Plus difficile au corps à corps. Reviens plus tard si besoin."}, [36]={hint="Retrouver le Signe de la Terre pour Garek."}, [37]={hint="Collecter 7 Morceaux de métal pour Sigrun."}, [38]={npc="Lotwil Veriatus", tgt="Lotwil Veriatus"}, [39]={npc="Rigglefuzz", tgt="Rigglefuzz"}, [40]={npc="Martek l'Exilé", tgt="Martek l'Exilé"}, [41]={npc="Martek l'Exilé", tgt="Martek l'Exilé"}, [42]={npc="Garek", tgt="Garek"}, [43]={npc="Sigrun Ironhew", tgt="Sigrun Ironhew"}, [44]={npc="Prospecteur Ironband", tgt="Prospecteur Ironband"}, [45]={npc="Ghak Healtouch", tgt="Ghak Healtouch"}, [46]={to="Ironforge"}, [47]={text="Barre d'argent"}, [48]={npc="Eglantine", tgt="Eglantine", desc="Apporte-la à Cabestan et rends-la à Menara Voidrender, puis prends Fragments de l'Orbe d'Orahil."}, [49]={npc="Eglantine", tgt="Eglantine", desc="Invocation d'un palefroi corrompu : rends-la à Strahad Farsan à Cabestan."}, [50]={npc="