    ["05-d9"] = {name="Uldaman", entrance="Terres ingrates 44.60, 12.10", steps={[1]={npc="Krom Stoutarm", tgt="Krom Stoutarm", tag="Groupe recommandé, Facultatif"}, [2]={npc="Prospecteur Foudrepique", tgt="Prospecteur Foudrepique", tag="Groupe recommandé, Facultatif"}, [3]={npc="Conseiller Belgrum", tgt="Conseiller Belgrum", tag="Facultatif, Groupe recommandé"}, [4]={npc="Rigglefuzz", tgt="Rigglefuzz", tag="Facultatif"}, [5]={npc="Carte chiffonnée", npcObj=true, tag="Prérequis de donjon"}, [6]={npc="Prospecteur Ryedol", tgt="Prospecteur Ryedol", tag="Prérequis de donjon"}, [7]={npc="Prospecteur Ryedol", tgt="Prospecteur Ryedol", tag="Facultatif"}, [8]={npc="Theldurin l'Egaré", tgt="Theldurin l'Egaré", tag="Facultatif"}, [9]={npc="Prospecteur Ironband", tgt="Prospecteur Ironband", tag="Prérequis de donjon"}, [10]={npc="Squelette de nain décrépi", npcObj=true, tag="Prérequis de donjon"}, [11]={npc="Squelette de nain décrépi", npcObj=true, tag="Prérequis de donjon"}, [12]={hint="Tuer l'assassin d'Agmond : Murdaloc.", tag="Prérequis de donjon"}, [13]={npc="Prospecteur Ironband", tgt="Prospecteur Ironband", tag="Prérequis de donjon"}, [14]={npc="Prospecteur Ironband", tgt="Prospecteur Ironband", tag="Facultatif"}, [15]={npc="Ghak Healtouch", tgt="Ghak Healtouch", tag="Prérequis de donjon"}, [16]={hint="Aller chercher les réactifs dont Ghak Healtouch a besoin dans les Terres ingrates, puis les lui rapporter à Thelsamar.", tag="Prérequis de donjon"}, [17]={npc="Ghak Healtouch", tgt="Ghak Healtouch", tag="Prérequis de donjon"}, [18]={npc="Ghak Healtouch", tgt="Ghak Healtouch", tag="Facultatif"}, [19]={text="Entrée : Uldaman"}, [20]={npc="Hammertoe Grez", tgt="Hammertoe Grez"}, [21]={npc="Hammertoe Grez", tgt="Hammertoe Grez"}, [22]={hint="Trouver l'Amulette de Hammertoe et lui rapporter à Uldaman."}, [23]={npc="Hammertoe Grez", tgt="Hammertoe Grez"}, [24]={npc="Hammertoe Grez", tgt="Hammertoe Grez"}, [25]={hint="Apporter 8 Pierres de puissance Dentrium et 8 Pierres de puis