nik"}, [52]={npc="Conseiller Belgrum", tgt="Conseiller Belgrum"}, [53]={npc="Conseiller Belgrum", tgt="Conseiller Belgrum", tag="Facultatif, Groupe recommandé"}, [54]={npc="Conseiller Belgrum", tgt="Conseiller Belgrum"}, [55]={npc="Historien Karnik", tgt="Historien Karnik"}, [56]={npc="Historien Karnik", tgt="Historien Karnik"}, [57]={npc="Grand Explorateur Magellas", tgt="Grand Explorateur Magellas"}, [58]={npc="Grand Explorateur Magellas", tgt="Grand Explorateur Magellas"}, [59]={npc="Dinita Stonemantle", tgt="Dinita Stonemantle"}, [60]={text="Second passage à Uldaman : vole de Forgefer à Thelsamar, va vers le sud-est dans les Terres ingrates et entre dans le donjon par l'entrée nord.", tag="Facultatif, Groupe recommandé", desc="Dernière partie de la chaîne du collier. Si ton groupe ne veut pas y retourner, passe-la jusqu'à la fin."}, [61]={npc="Restes d'un paladin", tgt="Restes d'un paladin", tag="Facultatif, Groupe recommandé", desc="Avance dans Uldaman jusqu'à Grimlok."}, [62]={npc="Restes d'un paladin", tgt="Restes d'un paladin", tag="Facultatif, Groupe recommandé"}, [63]={npc="Coupe de divination de Talvash", npcObj=true, tag="Facultatif, Groupe recommandé"}, [64]={npc="Coupe de divination de Talvash", npcObj=true, tag="Facultatif, Groupe recommandé"}, [65]={hint="Obtenir une Source d'énergie de la construction la plus puissante que vous pouvez trouver à Uldaman, puis la remettre à Talvash del Kissel à Forgefer.", tag="Facultatif, Groupe recommandé", desc="La source d'énergie est sur le boss final, Archaedas."}, [66]={to="Ironforge", tag="Facultatif", desc="Après le donjon, retourne à pied à Thelsamar et vole vers Forgefer."}, [67]={npc="Conseiller Belgrum", tgt="Conseiller Belgrum", tag="Facultatif, Groupe recommandé"}, [68]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Facultatif"}, [69]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Facultatif"}, [70]={npc="Talvash del Kissel", tgt="Talvash del Kissel", tag="Facultatif"}}},
    ["03-36"] = {steps={[1]={to="Darkshire", toA="{a:42}"}, [2]={npc="Maître de guet Sorigal", tgt="Maître de guet Sorigal"}, [3]={text="Depuis Sombre-comté, va vers l'est par le Défilé de Deuillevent jusqu'au Marais des Chagrins."}, [4]={npc="Gardien Biggs", tgt="Gardien Biggs"}, [5]={hint="Apporter 10 Grains de Poussière de rêve à Krazek à Baie-du-Butin. La Poussière de rêve se récupère sur les dragonnets du marais des Chagrins."}, [6]={hint="Tuez 8 jeunes crocilisques dents-de-scie, 10 tisseuses des pleurs et 10 jaguars du marécage, puis retournez voir le gardien Biggs, dans le marais des Chagrins."}, [7]={npc="Gardien Biggs", tgt="Gardien Biggs"}, [8]={npc="Gardien Biggs", tgt="Gardien Biggs"}, [9]={npc="Gourdin de Noboru", npcObj=true, tag="Facultatif", desc="Fais un clic droit sur Gourdin de Noboru dans ton sac pour lancer la quête. Tue Noboru le Gourdin pour obtenir un gourdin gris et fais un clic droit dessus pour lancer la quête."}, [10]={npc="Magtoor", tgt="Magtoor", tag="Facultatif"}, [11]={npc="Magtoor", tgt="Magtoor"}, [12]={hint="Apporter 6 Cristaux de draenéthyste à Magtoor au Havre boueux du marais des Chagrins."}, [13]={hint="Trouver le Coffre de la Caravane, dans le Sanctuaire des friches, obtenir les Composants pour les sorciers, et les apporter au Gardien Biggs."}, [14]={npc="Galen Goodward", tgt="Galen Goodward"}, [15]={hint="Escorter Galen jusqu'à ce qu'il soit hors de danger, puis trouver son camp dans le marais des Chagrins et ouvrir son coffre.", tag="Escorte", desc="Suis Galen hors du Sanctuaire des friches (le camp des Perdus); les monstres sur le chemin l'attaquent, protège-le; après l'escorte, va à son camp et ouvre le coffre-fort."}, [16]={npc="Coffre de Galen", npcObj=true}, [17]={npc="Magtoor", tgt="Magtoor"}, [18]={npc="Gardien Biggs", tgt="Gardien Biggs"}, [19]={npc="Gardien Biggs", tgt="Gardien Biggs"}, [20]={text="Suis la route jusqu'à ce point."}, [21]={hint="Apporter 8 Morceaux de Bois séché au soleil au Gardien Biggs dans le marais des Chagrins."}, [22]={hint="Brohann Caskbelly à Hurlevent veut que vous recherchiez le temple d'Atal'Hakkar.", desc="Se termine quand tu t'approches du temple englouti."}, [23]={npc="Gardien Biggs", tgt="Gardien Biggs"}, [24]={npc="Gardien Biggs", tgt="Gardien Biggs"}, [25]={text="Depuis le sud du Marais des Chagrins, entre dans les Terres foudroyées et suis la route vers le sud jusqu'au Rempart-du-Néant.", tag="Point de vol pas encore débloqué : la première fois, va-y à pied."}, [26]={npc="Intendant Lungertz", tgt="Intendant Lungertz"}, [27]={nodeA="{a:1438}", node="Nethergarde Keep"}}},
    ["03-37"] = {tips={{k="提醒", text="Rog'mar, au centre de la carte, est une ville de la Horde; n'approche pas.", s={{"Rog'mar, au centre de la carte, est une ville de la Horde; n'approche pas"}}}}, steps={[1]={to="Farholde Keep", toA="{a:16724}", tag="Avant de partir pour Rives Claires, tu peux acheter à l'hôtel des ventes (ou te faire envoyer par un reroll) 20 × Etoffe de tisse-mage (pour Panser les plaies).", desc="Tu feras escale à Sombre-comté et à Comté-du-Lac."}, [2]={npc="Demar Brant", tgt="Demar Brant"}, [3]={npc="Demar Brant", tgt="Demar Brant"}, [4]={npc="Demar Brant", tgt="Demar Brant", desc="Tu dois d'abord rendre le Registre du grand maréchal déclenché par un butin, sinon tu ne pourras pas la prendre."}, [5]={npc="Ashe Ambrehall", tgt="Ashe Ambrehall"}, [6]={npc="Bertrand Front-de-fer", tgt="Bertrand Front-de-fer"}, [7]={npc="Frère Lowley", tgt="Frère Lowley", tag="Facultatif, Nécessite du matériel", desc="Il faut 20 × Etoffe de tisse-mage. S'achète à l'hôtel des ventes. Passe si tu ne les as pas sur toi."}, [8]={npc="Frère Lowley", tgt="Frère Lowley", tag="Facultatif"}, [9]={npc="Frère Lowley", tgt="Frère Lowley"}, [10]={hint="Pansez les plaies de 3 soldats blessés pour frère Lowley.", desc="Les soldats blessés sont juste à côté de Frère Lowley."}, [11]={npc="Frère Lowley", tgt="Frère Lowley"}, [12]={npc="Frère Lowley", tgt="Frère Lowley"}, [13]={npc="Soeur Rolande", tgt="Soeur Rolande"}, [14]={npc="Tessa Aube-Radieuse", tgt="Tessa Aube-Radieuse"}, [15]={hint="Trouvez 6 pommes fraîches pour Tessa Aube-Radieuse, au donjon de Fort-Lointain.", desc="Les pommes fraîches sont sous les arbres fruitiers près de Fort-Lointain."}, [16]={npc="Tessa Aube-Radieuse", tgt="Tessa Aube-Radieuse"}, [17]={npc="Tessa Aube-Radieuse", tgt="Tessa Aube-Radieuse"}, [18]={hint="Récupérez 3 fourrures de coyote pour Tessa Aube-Radieuse, au donjon de Fort-Lointain."}, [19]={npc="Tessa Aube-Radieuse", tgt="Tessa Aube-Radieuse"}, [20]={npc="Tessa Aube-Radieuse", tgt="Tessa Aube-Radieuse"}, [21]={npc="Guetteur Cornélius", tgt="Guetteur Cornélius"}, [22]={text="Depuis le guet de Terral, va vers l'ouest, en passant au sud de Clairsoleil, jusqu'au sergent Faillan devant Suaire du Crépuscule. En passant au camp de bûcherons de Turner, ramasse le bois."}, [23]={hint="Ramassez 10 tas de bois au camp de bûcherons de Turner pour Bertrand Front-de-fer, du donjon de Fort-Lointain.", desc="Le tas de bois est au camp de bûcherons de Turner."}, [24]={npc="Sergent Faillan", tgt="Sergent Faillan"}, [25]={npc="Sergent Faillan", tgt="Sergent Faillan"}, [26]={npc="Sergent Faillan", tgt="Sergent Faillan"}, [27]={npc="Sergent Faillan", tgt="Sergent Faillan"}, [28]={hint="Invoquez un esclave du Crépuscule depuis un conduit du Suaire du Crépuscule et capturez-le à l'aide de la pierre d'âme d'Ambrehall.", desc="Au conduit du Suaire du Crépuscule, invoque un Esclave du Crépuscule et capture-le avec une pierre d'âme."}, [29]={npc="Maréchal Ryan", tgt="Maréchal Ryan"}, [30]={npc="Maréchal Ryan", tgt="Maréchal Ryan"}, [31]={hint="Secourez 5 éclaireurs de Fort-Lointain au Suaire du Crépuscule pour le sergent Faillan.", desc="Les éclaireurs sont prisonniers dans toute la Couronne du Crépuscule."}, [32]={hint="Éliminez 8 fanatiques du Crépuscule, 8 corrupteurs du crépuscule et 8 champions du Crépuscule au Suaire du Crépuscule pour le sergent Faillan."}, [33]={hint="Terrassez 5 mineurs ogres et 5 subjugateurs du Crépuscule dans la grotte proche du Suaire du Crépuscule pour le sergent Faillan."}, [34]={npc="Sergent Faillan", tgt="Sergent Faillan"}, [35]={npc="Sergent Faillan", tgt="Sergent Faillan"}, [36]={npc="Sergent Faillan", tgt="Sergent Faillan"}, [37]={npc="Sergent Faillan", tgt="Sergent Faillan", tag="Facultatif, Groupe recommandé", desc="Suzerain Kilgar est un élite de niveau 46."}, [38]={hint="Terrassez le suzerain Kilgar dans le Suaire du Crépuscule et rapportez sa tête au sergent Faillan.", tag="Facultatif, Groupe recommandé", desc="Suzerain Kilgar est un élite de niveau 46."}, [39]={npc="Sergent Faillan", tgt="Sergent Faillan", tag="Facultatif, Groupe recommandé", desc="Suzerain Kilgar est un élite de niveau 46."}, [40]={npc="Sergent Faillan", tgt="Sergent Faillan", desc="Tu dois d'abord vaincre Suzerain Kilgar."}, [41]={text="Va vers l'est par Clairsoleil et au sud du guet de Terral jusqu'à Port de Poudremèche, en évitant Rog'mar, la ville de la Horde. Port de Poudremèche n'a pas de point de vol de l'Alliance."}, [42]={npc="Slibo Bekdanlo", tgt="Slibo Bekdanlo", desc="Slibo est un peu au nord de la route vers Port de Poudremèche."}, [43]={hint="Récupérez 8 fioles d'émanations du marécage pour Slibo Bekdanlo.", desc="Récupère le gaz des marais aux évents près de Slibo."}, [44]={npc="Slibo Bekdanlo", tgt="Slibo Bekdanlo"}, [45]={npc="Slibo Bekdanlo", tgt="Slibo Bekdanlo"}, [46]={hint="Aidez Slibo à tester sa création."}, [47]={npc="Slibo Bekdanlo", tgt="Slibo Bekdanlo"}, [48]={npc="Peau peinte", npcObj=true, desc="Avant d'entrer à Port de Poudremèche, fais un détour vers le sud pour la ramasser ici (à environ 12 unités de carte de la route principale), puis rends-la à Argo Sifflécume en arrivant au port."}, [49]={npc="Gray Aube-Radieuse", tgt="Gray Aube-Radieuse"}, [50]={npc="Friz Faiblétincelle", tgt="Friz Faiblétincelle"}, [51]={npc="Friz Faiblétincelle", tgt="Friz Faiblétincelle"}, [52]={npc="Friz Faiblétincelle", tgt="Friz Faiblétincelle"}, [53]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [54]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [55]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [56]={npc="Fimbo Lubrimitz", tgt="Fimbo Lubrimitz"}, [57]={npc="AVIS DE RECHERCHE", npcObj=true, desc="Traquepince est sur la côte à l'est de Port de Poudremèche."}, [58]={npc="AVIS DE RECHERCHE", npcObj=true, tag="Groupe recommandé, Facultatif", desc="Vieil Appât-Pourri est un murloc élite de niveau 42 qui rôde autour des îles des murlocs au sud de Port de Poudremèche."}, [59]={npc="Traquepince", tgt="Argo Sifflécume"}, [60]={npc="Traquepince", tgt="Argo Sifflécume"}, [61]={hint="Apportez la pince de Traquepince à Fimbo Lubrimitz."}, [62]={hint="Tuez 10 boucaniers des mers de l'Est et 10 mousquetaires des mers de l'Est le long du rivage d'Estevent, au nord du port de Poudremèche."}, [63]={hint="Récupérez 8 marchandises de contrebande pour Friz Faiblétincelle au port de Poudremèche.", desc="Tue les boucaniers et mousquetaires des mers de l'Est en même temps que Concurrence déloyale."}, [64]={npc="Fimbo Lubrimitz", tgt="Fimbo Lubrimitz"}, [65]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [66]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [67]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [68]={npc="Friz Faiblétincelle", tgt="Friz Faiblétincelle"}, [69]={npc="Friz Faiblétincelle", tgt="Friz Faiblétincelle"}, [70]={hint="Volez 5 barils de poudre des mers de l'Est pour le maître des quais Sifflebruit.", desc="Les barils de poudre sont dans les bâtiments des ruines de Windbreak."}, [71]={hint="Tuez 8 écumeurs des mers de l'Est et 8 bombardiers des mers de l'Est pour le maître des quais Sifflebruit."}, [72]={hint="Récupérez 15 entrailles de bête et 8 champignons cadavériques pour Argo Sifflécume.", desc="Les entrailles se récupèrent sur les bêtes le long du chemin; les champignons cadavériques sont dans la grotte à côté de Windbreak, et il y a des ogres à l'intérieur."}, [73]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [74]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [75]={npc="Traquepince", tgt="Argo Sifflécume"}, [76]={npc="Traquepince", tgt="Argo Sifflécume"}, [77]={hint="Tuez 8 oracles murlocs et 9 guerriers murlocs le long du rivage d'Estevent."}, [78]={hint="Récupérez 12 yeux de Murloc et 6 morceaux de chair de clampant des sables pour Fimbo Lubrimitz."}, [79]={hint="Apportez une preuve de la mort du vieil Appât-Pourri au maître des quais Sifflebruit.", tag="Groupe recommandé, Facultatif"}, [80]={hint="Appâtez le monstre marin grâce au large amas d'appâts, puis apportez sa tête à Argo Sifflécume.", desc="Utilise l'appât près de l'épave engloutie, sous l'eau, à l'île des murlocs pour faire venir le monstre marin, bats-le puis ramasse sa tête. Fais-le dans le même passage que les murlocs et les crabes de la côte sud."}, [81]={npc="Fimbo Lubrimitz", tgt="Fimbo Lubrimitz"}, [82]={npc="Traquepince", tgt="Argo Sifflécume"}, [83]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [84]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit", tag="Groupe recommandé, Facultatif"}, [85]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [86]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit", tag="Facultatif", desc="Quête de niveau 45. Si elle a 3 niveaux de plus que toi ou davantage, tu peux la sauter d'abord."}, [87]={hint="Placez une charge explosive déclenchable à distance sur les trois bateaux des mers de l'Est.", desc="Place un explosif sur chacun des trois navires des boucaniers des mers de l'Est."}, [88]={hint="Livrez la surprise de Friz au capitaine Courbepièce, au rivage d'Estevent.", desc="Après avoir fait sauter les navires, apporte-le le long de la côte vers le nord-est pour le rendre."}, [89]={npc="Capitaine Haynes", tgt="Capitaine Courbepièce"}, [90]={npc="Capitaine Haynes", tgt="Capitaine Haynes"}, [91]={hint="Terrassez l'amiral Lamora et trouvez où se cachent ses trésors. Ensuite, rapportez le butin au maître des quais Sifflebruit.", tag="Facultatif", desc="Quête de niveau 45. Si elle a 3 niveaux de plus que toi ou davantage, tu peux la sauter d'abord."}, [92]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit"}, [93]={npc="Maître des quais Sifflebruit", tgt="Maître des quais Sifflebruit", tag="Facultatif"}, [94]={npc="Friz Faiblétincelle", tgt="Friz Faiblétincelle"}, [95]={npc="Friz Faiblétincelle", tgt="Friz Faiblétincelle", desc="Rends-la au Caravanier Ruzzgot à Baie-du-Butin; c'est sur ton chemin la prochaine fois que tu iras dans la Vallée de Strangleronce."}, [96]={npc="Friz Faiblétincelle", tgt="Friz Faiblétincelle", desc="Rends-la au maître des quais Pétivape à Port Gentepression, en Tanaris; c'est sur ton chemin quand tu iras en Tanaris plus tard."}, [97]={npc="Friz Faiblétincelle", tgt="Friz Faiblétincelle", desc="À rendre au Bastion de Pennelune, en Féralas. C'est sur le chemin quand tu iras en Féralas."}, [98]={text="Depuis Port de Poudremèche, retourne vers le sud-ouest à Fort-Lointain."}, [99]={npc="Bertrand Front-de-fer", tgt="Bertrand Front-de-fer"}, [100]={npc="Ashe Ambrehall", tgt="Ashe Ambrehall"}, [101]={npc="Ashe Ambrehall", tgt="Ashe Ambrehall", desc="Tu dois d'abord vaincre Suzerain Kilgar."}, [102]={npc="Demar Brant", tgt="Demar Brant"}, [103]={npc="Demar Brant", tgt="Demar Brant"}, [104]={npc="Demar Brant", tgt="Demar Brant"}, [105]={npc="Demar Brant", tgt="Demar Brant", desc="Tu dois d'abord vaincre Suzerain Kilgar."}, [106]={to="Stormwind", desc="Tu feras escale à Comté-du-Lac. Si tu n'as pas Derniers mots ni La menace du Crépuscule, inutile d'entrer à Hurlevent : si ta pierre de foyer est prête, rentre directement à Baie-du-Butin; si ta pierre de foyer est en recharge, vole de Fort-Lointain à Baie-du-Butin via Comté-du-Lac et Hurlevent."}, [107]={npc="Abigail Lawson", tgt="Abigail Lawson"}, [108]={npc="Généralissime Bolvar Fordragon", tgt="Généralissime Bolvar Fordragon", desc="Tu dois d'abord vaincre Suzerain Kilgar."}, [109]={bindA="{a:35}", desc="Si ta pierre de foyer n'est pas liée à Baie-du-Butin ou est encore en recharge : depuis Hurlevent, vole directement à Baie-du-Butin; si tu es encore à Fort-Lointain, fais escale à Comté-du-Lac et Hurlevent."}, [110]={npc="Krazek", tgt="Krazek"}, [111]={npc="Krazek", tgt="Krazek"}, [112]={to="Ratchet", toA="{a:392}", from="Booty Bay", fromA="{a:35}"}}},
    ["03-38"] = {steps={[1]={npc="Klannoc Macleod", tgt="Klannoc Macleod"}, [2]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Vaincs quatre vagues d'adversaires d'affilée dans l'arène de l'île de la Dispute."}, [3]={hint="Tuer le Grand Will et parler à Klannoc Macleod sur l'île de la Dispute.", desc="Vaincs quatre vagues d'adversaires d'affilée dans l'arène de l'île de la Dispute."}, [4]={npc="Klannoc Macleod", tgt="Klannoc Macleod", desc="Vaincs quatre vagues d'adversaires d'affilée dans l'arène de l'île de la Dispute."}, [5]={npc="Klannoc Macleod", tgt="Klannoc Macleod"}, [6]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Il te faut une Robe d'Arcana. Demande à un tailleur ou achète-la à l'hôtel des ventes."}, [7]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Il te faut une Robe d'Arcana. Demande à un tailleur ou achète-la à l'hôtel des ventes."}, [8]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Barre d'or ×1 s'achète à l'hôtel des ventes."}, [9]={hint="Apporter une Barre d'or à Xizk Goodstitch dans la vallée de Strangleronce."}, [10]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch", desc="Prends le bateau de Cabestan à Baie-du-Butin."}, [11]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch"}, [12]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Prends le bateau de Baie-du-Butin pour retourner à Cabestan."}, [13]={npc="Menara Voidrender", tgt="Menara Voidrender"}, [14]={hint="Apporter 10 Fioles de sang de Fielfurie et 1 Pierre infernale inférieure à Menara Voidrender dans les Tarides."}, [15]={npc="Menara Voidrender", tgt="Menara Voidrender"}, [16]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch", desc="Prends le bateau de Cabestan à Baie-du-Butin."}, [17]={npc="Xizk Goodstitch", tgt="Xizk Goodstitch"}, [18]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Prends le bateau de Baie-du-Butin pour retourner à Cabestan."}, [19]={hint="Apporter du Fil d'or fin, 2 Charbons ardents et un Fragment d'âme à Menara Voidrender dans les Tarides.", desc="Partie d'Arathi : prends le bateau de Cabestan à Baie-du-Butin, puis vole vers le Refuge de l'Ornière (avec escales à Hurlevent et Forgefer). Au retour, fais le trajet inverse."}, [20]={npc="Menara Voidrender", tgt="Menara Voidrender"}, [21]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Récompense : Robe sanglante dorée enchantée."}, [22]={hint="Attendre que Menara Voidrender ait terminé votre robe puis lui parler de nouveau.", desc="Récompense : Robe sanglante dorée enchantée."}, [23]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Récompense : Robe sanglante dorée enchantée."}, [24]={npc="Menara Voidrender", tgt="Menara Voidrender"}, [25]={npc="Menara Voidrender", tgt="Menara Voidrender"}, [26]={npc="Acolyte Wytula", tgt="Acolyte Wytula", desc="Fragment de gangrechien. Choisis entre celle-ci et Eclat d'Infernal."}, [27]={npc="Acolyte Magaz", tgt="Acolyte Magaz", tag="Facultatif", desc="Fragment d'infernal. Choisis entre celle-ci et Un éclat de gangrechien."}, [28]={hint="Parler aux acolytes de Menara dans la tour qui domine Ratchet et choisir de suivre l'une de leurs voies."}, [29]={hint="Prendre le Rubis de Felhas et l'utiliser sur l'un des gangrechiens de Désolace. Quand vous aurez réussi, rapporter le Rubis de Felhas et l'Esprit de gangrechien emprisonné à Menara Voidrender, dans les Tarides.", desc="Fragment de gangrechien. Choisis entre celle-ci et Eclat d'Infernal."}, [30]={hint="Prendre l'Emeraude d'Infus et l'utiliser sur les Infernaux qui se trouvent en Désolace. Quand vous aurez réussi, rapporter l'Emeraude d'Infus et l'Esprit d'Infernal emprisonné à Menara Voidrender, dans les Tarides.", tag="Facultatif", desc="Fragment d'infernal. Choisis entre celle-ci et Un éclat de gangrechien."}, [31]={npc="Menara Voidrender", tgt="Menara Voidrender", desc="Fragment de gangrechien. Choisis entre celle-ci et Eclat d'Infernal."}, [32]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Facultatif", desc="Fragment d'infernal. Choisis entre celle-ci et Un éclat de gangrechien."}, [33]={npc="Tabetha", tgt="Tabetha"}, [34]={npc="Tabetha", tgt="Tabetha", tag="Groupe recommandé, Facultatif"}, [35]={hint="Tuer le Démon de l'Orbe, puis parler à Tabetha.", tag="Groupe recommandé, Facultatif", desc="Le Démon de l'Orbe est un élite de niveau 40; trouve un groupe pour la faire."}, [36]={npc="Tabetha", tgt="Tabetha", tag="Groupe recommandé, Facultatif"}, [37]={npc="Tabetha", tgt="Tabetha", tag="Facultatif"}, [38]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Facultatif"}, [39]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Facultatif", desc="Fais celle-ci si tu as choisi le fragment de gangrechien."}, [40]={hint="Attendre que Menara Voidrender termine l'Orbe de Dar'Orahil, puis lui reparler.", tag="Facultatif", desc="Fais celle-ci si tu as choisi le fragment de gangrechien."}, [41]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Facultatif", desc="Fais celle-ci si tu as choisi le fragment de gangrechien."}, [42]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Facultatif", desc="Fais celle-ci si tu as choisi le fragment d'infernal."}, [43]={hint="Attendre que Menara Voidrender ait terminé l'Orbe de Noh'Orahil, puis lui reparler.", tag="Facultatif", desc="Fais celle-ci si tu as choisi le fragment d'infernal."}, [44]={npc="Menara Voidrender", tgt="Menara Voidrender", tag="Facultatif", desc="Fais celle-ci si tu as choisi le fragment d'infernal."}, [45]={npc="Strahad Farsan", tgt="Strahad Farsan"}, [46]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Rends la quête pour apprendre Invocation d'un palefroi corrompu."}, [47]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Rends la quête pour apprendre Invocation d'un palefroi corrompu."}, [48]={to="Stonetalon Peak", toA="{a:467}", desc="Si tu as débloqué la Combe de Nijel, vole directement (avec escale à Theramore) et saute l'étape suivante. Si le Pic des Serres-Rocheuses n'est pas débloqué, vole jusqu'à Astranaar et entre dans les Serres-Rocheuses par la grotte au sud d'Orneval."}, [49]={text="Depuis le Pic des Serres-Rocheuses, suis la route vers le sud en descendant la montagne, contourne le camp de la Horde en passant par la Retraite de Roche-Soleil, puis entre en Désolace par le sud-ouest des Serres-Rocheuses. La Combe de Nijel se trouve au nord de Désolace.", tag="Point de vol pas encore débloqué : la première fois, va-y à pied."}, [50]={to="Nijel's Point", toA="{a:608}"}, [51]={nodeA="{a:608}", node="Nijel's Point"}, [52]={npc="Frère Anton", tgt="Frère Anton"}, [53]={npc="Capitaine Pentigast", tgt="Capitaine Pentigast", tag="Facultatif", desc="Les centaures de tous les clans en donnent, mais cette étape ne fait pas tuer de centaures en chemin, et les monstres du Village des Kolkar sont d'un niveau plutôt bas; fais-la si tu veux un peu plus d'expérience."}, [54]={hint="Récupérez 5 totems centaures sculptés en tuant des Centaures de n'importe quel clan un peu partout en Désolace, puis rapportez-les au capitaine Pentigast à la combe de Nijel.", tag="Facultatif"}, [55]={npc="Hornizz Brimbuzzle", tgt="Hornizz Brimbuzzle"}, [56]={hint="Détruire 30 Ravageurs morts-vivants, puis retourner voir Frère Anton, à la Combe de Nijel."}, [57]={hint="Apporter 8 Fantôm-o-plasmes et la Caisse d'aimants fantômes à Hornizz Brimbuzzle, en Désolace."}, [58]={npc="Hornizz Brimbuzzle", tgt="Hornizz Brimbuzzle"}, [59]={npc="Frère Anton", tgt="Frère Anton"}, [60]={npc="Frère Anton", tgt="Frère Anton", tag="Facultatif, Groupe recommandé"}, [61]={npc="Capitaine Pentigast", tgt="Capitaine Pentigast", tag="Facultatif"}, [62]={hint="Récupérez 5 totems de feu tordus, 5 totems de terre tordus, 5 totems d'air tordus et 5 totems d'eau tordus pour Veyric Hametonne dans les hautes-terres Arathies.", tag="Facultatif", desc="Le totem d'air est sur les centaures maraudines d'ici; le totem d'eau sur les murlocs Aileron boueux du nord du Marécage d'Âprefange, le totem de feu sur les troggs Cavepierre des Terres ingrates et le totem de terre sur les Perdus du Marais des Chagrins : ramasse-les au passage."}}},
    ["03-39"] = {grind={[1]={mob="Explorateur naga", note="Côte au nord de Baie-du-Butin; monstres normaux, bien regroupés."}, [2]={mob="Matelot de la Voile sanglante", note="Le camp de la Voile sanglante sur la plage au sud; les mêmes monstres que pour les quêtes de la Voile sanglante."}}, steps={[1]={bindA="{a:35}", desc="Si ta pierre de foyer est en recharge, vole de la Combe de Nijel à Cabestan (avec escale à Theramore), puis prends le bateau pour Baie-du-Butin."}, [2]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [3]={npc="Crank Fizzlebub", tgt="Crank Fizzlebub"}, [4]={npc="Deeg", tgt="Deeg"}, [5]={npc="Kebok", tgt="Kebok"}, [6]={npc="Amiral Seahorn", tgt="Amiral Seahorn"}, [7]={npc="Corsaire Bloads", tgt="Corsaire Bloads"}, [8]={npc="MacKinley Loup des mers", tgt="MacKinley Loup des mers"}, [9]={npc="Dizzy le Borgne", tgt="Dizzy le Borgne"}, [10]={npc="Caravanier Ruzzgot", tgt="Caravanier Ruzzgot"}, [11]={hint="L'amiral Seahorn à Baie-du-Butin veut que vous tuiez 10 Bretteurs de la Voile sanglante et que vous rapportiez les Cartes de la Voile sanglante et les Ordres de la Voile sanglante.", desc="Cherche des bouteilles le long de la plage : en ramasser une lance une quête."}, [12]={hint="Deeg de Baie-du-Butin veut que vous lui apportiez 15 portions de Tabac à priser."}, [13]={hint="Dizzy le Borgne de Baie-du-Butin veut que vous récupériez son œil chez les boucaniers de la Voile sanglante."}, [14]={hint="Apporter 10 Tas de roseaux akiris au corsaire Bloads à Baie-du-Butin."}, [15]={hint="Acquérir 6 Bracelets d'élémentaires d'eau pour le baron Revilgaz à Baie-du-Butin.", tag="Facultatif"}, [16]={npc="Corsaire Bloads", tgt="Corsaire Bloads"}, [17]={npc="Corsaire Bloads", tgt="Corsaire Bloads"}, [18]={npc="Whiskey Slim", tgt="Whiskey Slim"}, [19]={npc="Deeg", tgt="Deeg"}, [20]={npc="Amiral Seahorn", tgt="Amiral Seahorn"}, [21]={npc="Amiral Seahorn", tgt="Amiral Seahorn", tag="Facultatif"}, [22]={npc="Dizzy le Borgne", tgt="Dizzy le Borgne", desc="Achète à l'hôte