    [96782] = {n="Extraction clandestine", d="Retrouvez la lame de la maison Perenolde et l'égide royale de Perenolde dans les ruines d'Alterac. Rapportez-les ensuite à Myrokos Sourdeforme."},
    [96783] = {n="Un moyen d'infiltration", d="Volez un uniforme du Syndicat au manoir de Nordclos afin d'infiltrer le donjon de Stromgarde."},
