    [96785] = {n="Motus", d="Dans le donjon de Stromgarde, trouvez de quoi convaincre Anastasia de vous révéler les détails de cette transaction secrète."},
    [96786] = {n="La piqûre du Syndicat", d="Interrompez la transaction secrète et récupérez l'objet destiné au Syndicat. Rapportez-le ensuite à Myrokos Sourdeforme, au manoir de Ravenholdt."},
